books.mjs.text:
// One set of books across every marketplace a reseller sells on.
//
// Each marketplace exports a different file, and each file hides a different
// part of the truth: eBay buries shipping labels and ads inside the same
// report as sales, Etsy spreads fees over three columns and a second file,
// Poshmark charges a flat fee that is invisible until it is divided out, and
// Whatnot splits commission and processing. The single-marketplace
// analyzers in this repository (`ebay-transaction-report-analyzer`,
// `etsy-statement-profit-analyzer`, `poshmark-sales-report-analyzer`,
// `whatnot-sales-report-analyzer`) each read one of them. This module reads
// the files together, so a seller with more than one channel gets one monthly
// profit and loss, one comparison of what each channel really keeps, and one
// worksheet laid out the way a tax preparer asks for it.
//
// The engines in ./engines are verbatim copies of those calc.mjs files,
// so the venture deploys on its own. `books.test.mjs` fails if a copy drifts
// from its source while the source still exists in the monorepo.
//
// Nothing here fetches anything. Files are read in the caller's browser tab.

import * as ebay from "./engines/ebay.mjs";
import * as etsy from "./engines/etsy.mjs";
import * as poshmark from "./engines/poshmark.mjs";
import * as whatnot from "./engines/whatnot.mjs";
import * as shopify from "./engines/shopify.mjs";

export const CHANNELS = {
  ebay: "eBay",
  etsy: "Etsy",
  poshmark: "Poshmark",
  whatnot: "Whatnot",
  shopify: "Shopify",
};

const r2 = (n) => Math.round(n * 100) / 100;

/** Header tokens of the first non-empty line, lower-cased. */
function headerTokens(text) {
  const line = String(text || "").split(/\r?\n/).find((l) => l.trim() !== "") || "";
  const delim = line.includes("\t") ? "\t" : line.split(";").length > line.split(",").length ? ";" : ",";
  return line.split(delim).map((h) => h.replace(/^﻿/, "").replace(/^"|"$/g, "").trim().toLowerCase());
}

/**
 * Which marketplace file is this? Decided from the header row alone, because
 * the Poshmark and Whatnot parsers will both accept each other's file and read
 * it wrongly (a Whatnot export has an "Order Date" too).
 *
 * eBay's report starts with a few lines of preamble before the header, so its
 * test looks for the header anywhere in the first lines.
 */
export function detectKind(text) {
  const head = String(text || "").split(/\r?\n/).slice(0, 15).join("\n").toLowerCase();
  if (/net amount/.test(head) && /(order number|transaction creation date)/.test(head)) return "ebay";
  const h = headerTokens(text);
  const has = (...names) => names.every((n) => h.some((x) => x === n));
  // Shopify Payments "Transactions" export: a payout status and a type per money
  // movement. Checked before the item-per-row formats, none of which has these.
  if (has("transaction date", "type", "amount") && h.some((x) => /^payout (status|id)$/.test(x))) return "shopify";
  // Shopify admin "Orders" export: one row per line item; only used to cost products.
  if (has("name", "lineitem name") && h.includes("financial status")) return "shopify-orders";
  if (h.includes("fees & taxes") && h.includes("net")) return "etsy";
  if (has("item name", "order id") && h.some((x) => /sale date|date sold/.test(x))) return "etsy-items";
  if (h.some((x) => /^poshmark fee$|^posh fee$/.test(x)) || (h.includes("brand") && h.some((x) => /order price/.test(x)))) return "poshmark";
  if (h.some((x) => /^commission$|^processing fee$|^show$|^show name$/.test(x)) || (h.includes("product name") && h.some((x) => /sold price/.test(x)))) return "whatnot";
  return null;
}

const emptyLine = (channel) => ({
  channel,
  label: CHANNELS[channel],
  orders: 0,
  sales: 0, // gross sales the marketplace recorded (item, and shipping where the file has it)
  refunds: 0, // negative
  platformFees: 0, // negative: commission, transaction, processing, listing and similar
  labels: 0, // negative: postage bought through the marketplace
  ads: 0, // negative: promoted listings, Etsy ads
  other: 0, // negative: anything else the file deducts
  net: 0, // what the marketplace says you kept before the cost of the goods
  cogs: null, // null when no cost was supplied for any sale on this channel
  costedShare: null, // share of the channel's sales (by count where known) that carry a cost
  profit: null,
  from: null,
  to: null,
  notes: [],
});

function ebayChannel(files, costText) {
  const out = emptyLine("ebay");
  const rows = [];
  const skipped = [];
  for (const f of files) {
    const n = ebay.normalizeReport(ebay.parseCsv(f.text));
    if (n.error) return { error: `${f.name}: ${n.error}` };
    rows.push(...n.rows);
    skipped.push(...(n.skipped || []));
  }
  const costs = costText ? ebay.parseCosts(costText) : { costs: {}, bad: [] };
  const r = ebay.analyze(rows, { costs: costs.costs });
  if (r.invalid) return { error: r.invalid };
  const s = r.summary;
  const b = s.feeBuckets;
  out.orders = s.orderCount;
  out.sales = s.sales;
  out.refunds = s.refunds;
  out.labels = b.labels;
  out.ads = b.ads;
  // The engines' platformFees already contains advertising; split it out so
  // the Schedule C worksheet can put ads on their own line.
  out.platformFees = r2(s.platformFees - b.ads);
  out.other = r2(s.operating - s.sales - s.refunds - b.labels - b.ads - out.platformFees);
  out.net = s.operating;
  out.from = s.firstMonth;
  out.to = s.lastMonth;
  if (s.anyCosted) {
    out.cogs = s.cogsTotal;
    out.costedShare = s.allCosted ? 1 : null;
    out.profit = s.profit;
    if (!s.allCosted) out.notes.push("Only some eBay items have a cost, so eBay profit is left blank rather than overstated.");
  }
  const months = r.months.map((m) => ({ month: m.key, sales: m.sales, refunds: m.refunds, deductions: r2(m.net - m.sales - m.refunds), net: m.net, cogs: null }));
  return { line: out, months, detail: r, skipped: skipped.length, costBad: costs.bad.length };
}

function etsyChannel(statements, itemFiles, costText) {
  const out = emptyLine("etsy");
  const rows = [];
  for (const f of statements) {
    const n = etsy.normalizeStatement(etsy.parseCsv(f.text));
    if (n.error) return { error: `${f.name}: ${n.error}` };
    rows.push(...n.rows);
  }
  const items = [];
  for (const f of itemFiles) {
    const n = etsy.normalizeItems(etsy.parseCsv(f.text));
    if (n && n.rows) items.push(...n.rows);
  }
  const costs = costText ? etsy.parseCosts(costText) : { costs: {}, bad: [] };
  const r = etsy.analyze(rows, items, { costs: costs.costs });
  if (r.invalid) return { error: r.invalid };
  const s = r.summary;
  const b = s.feeBuckets;
  out.orders = s.orderCount;
  out.sales = s.sales;
  out.refunds = s.refunds;
  out.labels = b.labels;
  out.ads = b.ads;
  // The engines' platformFees already contains advertising; split it out so
  // the Schedule C worksheet can put ads on their own line.
  out.platformFees = r2(s.platformFees - b.ads);
  out.other = r2(s.operating - s.sales - s.refunds - b.labels - b.ads - out.platformFees);
  out.net = s.operating;
  out.from = s.firstMonth;
  out.to = s.lastMonth;
  if (s.anyCosted && s.allCosted) {
    out.cogs = s.cogsTotal;
    out.profit = s.profit;
    out.costedShare = 1;
  } else if (costText && !items.length) {
    out.notes.push("Etsy costs are matched through the Sold Order Items file; add it to cost your Etsy sales.");
  }
  const months = r.months.map((m) => ({ month: m.key, sales: m.sales, refunds: m.refunds, deductions: r2(m.net - m.sales - m.refunds), net: m.net, cogs: null }));
  return { line: out, months, detail: r, costBad: costs.bad.length };
}

// Shopify's Transactions export records what the customer paid, which includes
// the sales tax and shipping collected on the order. Sales tax is the state's
// money, not income, so when the Orders export is given the tax on each charged
// order (less the share refunded) is taken out of both sales and net. Without
// it the charges are used as they are and the channel says so.
function shopifyChannel(txFiles, orderFiles, costText) {
  const out = emptyLine("shopify");
  const rows = [];
  let skipped = 0;
  for (const f of txFiles) {
    const n = shopify.normalizeTransactions(shopify.parseCsv(f.text));
    if (n.error) return { error: `${f.name}: ${n.error}` };
    rows.push(...n.rows);
    skipped += n.skipped.length;
  }
  const orders = [];
  for (const f of orderFiles) {
    const n = shopify.normalizeOrders(shopify.parseCsv(f.text));
    if (n.error) return { error: `${f.name}: ${n.error}` };
    orders.push(...n.orders);
  }
  const costs = costText ? shopify.parseCosts(costText) : { costs: {}, bad: [] };
  const r = shopify.analyze(rows, orders, { costs: costs.costs });
  if (r.invalid) return { error: r.invalid };
  const s = r.summary;
  const t = s.totals;

  const taxByMonth = {};
  let tax = 0;
  if (orders.length) {
    const byKey = new Map(r.orders.filter((o) => o.charged > 0).map((o) => [o.key, o]));
    for (const o of orders) {
      const tx = byKey.get(o.key);
      if (!tx || !(o.taxes > 0)) continue;
      const refundedShare = Math.min(1, Math.max(0, -tx.refunds / tx.charged));
      const kept = r2(o.taxes * (1 - refundedShare));
      tax = r2(tax + kept);
      taxByMonth[tx.month] = r2((taxByMonth[tx.month] || 0) + kept);
    }
  }

  out.orders = s.orderCount;
  out.sales = r2(s.charges - tax);
  out.refunds = r2(t.refunds);
  out.platformFees = r2(t.processing + t.gateway);
  out.net = r2(s.operating - tax);
  out.other = r2(out.net - out.sales - out.refunds - out.platformFees);
  out.from = s.firstMonth;
  out.to = s.lastMonth;
  if (orders.length) {
    if (tax > 0) out.notes.push(`$${tax.toFixed(2)} of sales tax collected was taken out of Shopify sales and payout (from the Orders export); it is owed to the state, not income.`);
  } else {
    out.notes.push("Shopify sales here include the sales tax and shipping customers paid, because no Orders export was given. Add it to take tax out and to cost products.");
  }
  if (s.anyCosted && s.allCosted) {
    out.cogs = s.cogsTotal;
    out.costedShare = 1;
    out.profit = r2(out.net - out.cogs);
  } else if (s.anyCosted) {
    out.notes.push("Only some Shopify products have a cost, so Shopify profit is left blank rather than overstated.");
  } else if (costText && !orders.length) {
    out.notes.push("Shopify costs are matched through the Orders export (by product name or SKU); add it to cost your Shopify sales.");
  }
  const months = r.months.map((m) => {
    const mt = taxByMonth[m.key] || 0;
    const sales = r2(m.charges - mt);
    const net = r2(m.net - mt);
    return { month: m.key, sales, refunds: r2(m.refunds), deductions: r2(net - sales - m.refunds), net, cogs: null };
  });
  return { line: out, months, detail: r, skipped, costBad: costs.bad.length };
}

function itemChannel(channel, engine, files, costText, feeMode) {
  const out = emptyLine(channel);
  const items = [];
  let skipped = 0;
  for (const f of files) {
    const delim = engine.detectDelimiter(f.text);
    const n = engine.normalizeRows(engine.parseCsv(f.text, delim), { decimalComma: delim === ";", feeMode });
    if (n.error) return { error: `${f.name}: ${n.error}` };
    items.push(...n.items);
    skipped += (n.skipped || []).length;
  }
  const r = engine.analyze(items, { costList: costText || "" });
  if (r.invalid) return { error: r.invalid };
  const s = r.summary;
  out.orders = s.items;
  out.sales = s.price;
  // The payout the file reports is what the seller kept; everything between
  // price and payout is a deduction. Fees are the named part of it.
  out.platformFees = -s.fee;
  out.other = r2(s.payout - s.price + s.fee);
  out.net = s.payout;
  out.from = engine.dateStr(s.from).slice(0, 7);
  out.to = engine.dateStr(s.to).slice(0, 7);
  if (s.costedItems > 0) {
    out.costedShare = s.costedItems / s.items;
    if (s.costedItems === s.items) {
      out.cogs = s.cost;
      out.profit = s.profit;
    } else {
      out.notes.push(`${s.costedItems} of ${s.items} ${CHANNELS[channel]} sales have a cost, so ${CHANNELS[channel]} profit is left blank rather than overstated.`);
    }
  }
  const months = r.byMonth.map((m) => ({
    month: m.label,
    sales: m.price,
    refunds: 0,
    deductions: r2(m.payout - m.price),
    net: m.payout,
    cogs: m.costedItems === m.items ? m.cost : null,
  }));
  return { line: out, months, detail: r, skipped, costBad: r.costList ? r.costList.errors.length : 0 };
}

/**
 * Build the books.
 *
 * @param {{name: string, text: string}[]} files  any mix of marketplace exports
 * @param {{costs?: string, feeMode?: "auto"|"schedule"}} opts
 *   `costs` is pasted `key,cost` lines, handed to each engine, which matches by
 *   its own key (eBay item title or number, SKU on the others).
 */
export function buildBooks(files, { costs = "", feeMode = "auto" } = {}) {
  const groups = { ebay: [], etsy: [], "etsy-items": [], poshmark: [], whatnot: [], shopify: [], "shopify-orders": [] };
  const unread = [];
  for (const f of files) {
    const kind = detectKind(f.text);
    if (kind) groups[kind].push(f);
    else unread.push(f.name);
  }
  if (!groups["etsy-items"].length || groups.etsy.length) {
    /* an items file alone is not a channel; it only costs Etsy sales */
  }
  const channels = [];
  const monthsBy = {};
  const problems = [];
  const details = {};
  const add = (key, res) => {
    if (res.error) {
      problems.push(res.error);
      return;
    }
    channels.push(res.line);
    details[key] = res.detail;
    for (const m of res.months) {
      (monthsBy[m.month] ||= {})[key] = m;
    }
    if (res.costBad) res.line.notes.push(`${res.costBad} cost line(s) were not understood.`);
    if (res.skipped) res.line.notes.push(`${res.skipped} row(s) were skipped as unreadable.`);
  };
  if (groups.ebay.length) add("ebay", ebayChannel(groups.ebay, costs));
  if (groups.etsy.length) add("etsy", etsyChannel(groups.etsy, groups["etsy-items"], costs));
  if (groups.poshmark.length) add("poshmark", itemChannel("poshmark", poshmark, groups.poshmark, costs, feeMode));
  if (groups.whatnot.length) add("whatnot", itemChannel("whatnot", whatnot, groups.whatnot, costs, feeMode));
  if (groups.shopify.length) add("shopify", shopifyChannel(groups.shopify, groups["shopify-orders"], costs));
  if (groups["shopify-orders"].length && !groups.shopify.length) {
    problems.push("A Shopify Orders export was given without the Shopify Payments Transactions export. The transactions file is the one with the fees; add it.");
  }
  if (groups["etsy-items"].length && !groups.etsy.length) {
    problems.push("A Sold Order Items file was given without the Etsy Payment Account statement. The statement is the one with the fees; add it.");
  }

  if (!channels.length) {
    return { invalid: problems[0] || "No marketplace file could be recognised. Expected an eBay Transaction report, an Etsy Payment Account statement, a Poshmark My Sales Report, a Whatnot orders export or a Shopify Payments Transactions export.", unread, problems };
  }

  // Combined months, newest last. Every row reconciles: sales + refunds +
  // deductions = net, by construction, per channel and in the total.
  const keys = Object.keys(monthsBy).sort();
  const months = keys.map((month) => {
    const per = monthsBy[month];
    const row = { month, sales: 0, refunds: 0, deductions: 0, net: 0, byChannel: {}, cogs: 0, costedChannels: 0, channelsPresent: 0 };
    for (const [key, m] of Object.entries(per)) {
      row.sales += m.sales;
      row.refunds += m.refunds;
      row.deductions += m.deductions;
      row.net += m.net;
      row.byChannel[key] = m.net;
      row.channelsPresent += 1;
      if (m.cogs !== null && m.cogs !== undefined) {
        row.cogs += m.cogs;
        row.costedChannels += 1;
      }
    }
    for (const k of ["sales", "refunds", "deductions", "net", "cogs"]) row[k] = r2(row[k]);
    row.profit = row.costedChannels === row.channelsPresent && row.channelsPresent > 0 ? r2(row.net - row.cogs) : null;
    return row;
  });

  const total = { sales: 0, refunds: 0, platformFees: 0, labels: 0, ads: 0, other: 0, net: 0, orders: 0 };
  for (const c of channels) for (const k of Object.keys(total)) total[k] = r2(total[k] + c[k]);
  const allCosted = channels.every((c) => c.profit !== null);
  total.cogs = allCosted ? r2(channels.reduce((a, c) => a + c.cogs, 0)) : null;
  total.profit = allCosted ? r2(channels.reduce((a, c) => a + c.profit, 0)) : null;
  total.keepRate = total.sales > 0 ? total.net / total.sales : null;

  for (const c of channels) {
    c.keepRate = c.sales > 0 ? c.net / c.sales : null;
    c.takeRate = c.sales > 0 ? -(c.platformFees + c.labels + c.ads + c.other) / c.sales : null;
    c.profitMargin = c.profit !== null && c.sales > 0 ? c.profit / c.sales : null;
  }

  return {
    channels,
    months,
    total,
    schedule: scheduleWorksheet(channels, total),
    findings: findings(channels, total, months),
    unread,
    problems,
    details,
  };
}

/**
 * A worksheet in the shape of the US Schedule C income and expense lines, so a
 * preparer receives numbers already grouped. It is arithmetic on the files, not
 * a return: where a line depends on how the seller treats an item (postage is
 * often cost of goods sold, sometimes "other expenses"), the row says which
 * lines a number could belong to and leaves the decision to the preparer.
 */
export function scheduleWorksheet(channels, total) {
  const neg = (v) => r2(-v);
  const rows = [
    { line: "1", label: "Gross receipts or sales", amount: r2(total.sales), note: "As the marketplaces recorded them. Compare with any 1099-K, which may also include sales tax and shipping." },
    { line: "2", label: "Returns and allowances", amount: neg(total.refunds), note: "Refunds the marketplaces deducted." },
    { line: "4 / 42", label: "Cost of goods sold", amount: total.cogs, note: total.cogs === null ? "Not computed: not every sale has a cost. Add costs, or use your purchase records." : "From the costs you supplied. Opening and closing inventory are not modelled." },
    { line: "8", label: "Advertising", amount: neg(total.ads), note: "Promoted listings and Etsy ads." },
    { line: "10", label: "Commissions and fees", amount: neg(total.platformFees), note: "Final value, transaction, processing, listing and commission fees." },
    { line: "27a / 4", label: "Postage bought through the marketplace", amount: neg(total.labels), note: "Shipping labels. Often reported inside cost of goods or as an other expense; ask your preparer which." },
    { line: "27a", label: "Other marketplace deductions", amount: neg(total.other), note: "Anything else between sales and payout (subscriptions, disputes, credits, shipping adjustments), net of credits." },
  ];
  return rows;
}

function findings(channels, total, months) {
  const out = [];
  if (channels.length >= 2) {
    const ranked = [...channels].filter((c) => c.sales > 0).sort((a, b) => b.keepRate - a.keepRate);
    const best = ranked[0];
    const worst = ranked[ranked.length - 1];
    if (best && worst && best !== worst) {
      out.push({
        severity: "info",
        title: `${best.label} keeps ${(best.keepRate * 100).toFixed(1)}% of every sale dollar; ${worst.label} keeps ${(worst.keepRate * 100).toFixed(1)}%`,
        detail: `That is before the cost of the goods. On ${best.label}, $100 of sales leaves $${(best.keepRate * 100).toFixed(2)} after fees, postage bought there, ads and refunds; on ${worst.label} it leaves $${(worst.keepRate * 100).toFixed(2)}. Compare like with like: a channel full of heavy items pays more in postage, which is not its fee.`,
      });
    }
  }
  for (const c of channels) {
    if (c.sales > 0 && c.ads / c.sales < -0.05) {
      out.push({ severity: "medium", title: `${c.label} advertising is ${((-c.ads / c.sales) * 100).toFixed(1)}% of sales`, detail: `${c.label} ads and promotions cost $${(-c.ads).toFixed(2)} against $${c.sales.toFixed(2)} of sales. Check the sales they brought against what you would have sold anyway.` });
    }
    if (c.sales > 0 && Math.abs(c.refunds) / c.sales > 0.05) {
      out.push({ severity: "medium", title: `${c.label} refunds are ${((Math.abs(c.refunds) / c.sales) * 100).toFixed(1)}% of sales`, detail: `$${Math.abs(c.refunds).toFixed(2)} was refunded on $${c.sales.toFixed(2)} of sales. Refunded sales also return no fee on some marketplaces.` });
    }
    for (const n of c.notes) out.push({ severity: "info", title: n.startsWith(c.label) ? n : `${c.label}: ${n}`, detail: "" });
  }
  const profitable = channels.filter((c) => c.profit !== null);
  if (profitable.length >= 2) {
    const byMargin = [...profitable].sort((a, b) => b.profitMargin - a.profitMargin);
    const a = byMargin[0];
    const z = byMargin[byMargin.length - 1];
    out.push({
      severity: "high",
      title: `After the cost of goods, ${a.label} earns ${(a.profitMargin * 100).toFixed(1)}¢ of profit per sales dollar and ${z.label} earns ${(z.profitMargin * 100).toFixed(1)}¢`,
      detail: `Profit is what the marketplace paid out minus what you paid for the goods. Sourcing and listing time are not counted, so a thinner channel can still win on hours spent.`,
    });
  }
  const costed = months.filter((m) => m.profit !== null);
  if (costed.length >= 3) {
    const worst = [...costed].sort((a, b) => a.profit - b.profit)[0];
    if (worst.profit < 0) out.push({ severity: "high", title: `${worst.month} lost $${(-worst.profit).toFixed(2)} after the cost of goods`, detail: "The month's marketplace payouts were smaller than what you paid for the items sold in it." });
  }
  return out;
}

export function toCsv(result) {
  const q = (v) => `"${String(v).replace(/"/g, '""')}"`;
  const f = (v) => (v === null || v === undefined ? "" : Number(v).toFixed(2));
  const head = "month,sales,refunds,marketplace_deductions,net_payout,cost_of_goods,profit";
  const lines = result.months.map((m) => [m.month, f(m.sales), f(m.refunds), f(m.deductions), f(m.net), m.costedChannels === m.channelsPresent ? f(m.cogs) : "", f(m.profit)].join(","));
  const chead = "\nchannel,orders,sales,refunds,fees,postage,ads,other,net_payout,cost_of_goods,profit,keeps_per_sales_dollar";
  const cl = result.channels.map((c) => [q(c.label), c.orders, f(c.sales), f(c.refunds), f(c.platformFees), f(c.labels), f(c.ads), f(c.other), f(c.net), f(c.cogs), f(c.profit), c.keepRate === null ? "" : c.keepRate.toFixed(4)].join(","));
  const shead = "\nschedule_c_line,label,amount";
  const sl = result.schedule.map((s) => [q(s.line), q(s.label), f(s.amount)].join(","));
  return [head, ...lines, chead, ...cl, shead, ...sl].join("\n");
}

export function summaryText(result) {
  const m = (v) => (v === null || v === undefined ? "–" : (v < 0 ? "-$" : "$") + Math.abs(v).toFixed(2));
  const out = [`Reseller books: ${result.channels.map((c) => c.label).join(", ")}`];
  const t = result.total;
  out.push(`Sales ${m(t.sales)}, refunds ${m(t.refunds)}, fees ${m(t.platformFees)}, postage ${m(t.labels)}, ads ${m(t.ads)}, other ${m(t.other)}, net payout ${m(t.net)}.`);
  out.push(t.profit === null ? "Profit not computed (not every sale has a cost)." : `Cost of goods ${m(t.cogs)}; profit ${m(t.profit)}.`);
  for (const c of result.channels) out.push(`${c.label}: ${c.orders} orders, sales ${m(c.sales)}, kept ${m(c.net)} (${(c.keepRate * 100).toFixed(1)}%)${c.profit === null ? "" : `, profit ${m(c.profit)}`}`);
  return out.join("\n");
}

/** Synthetic example: the engines' own made-up files, so no real seller appears. */
export function sampleFiles() {
  const e = ebay.sampleData();
  const t = etsy.sampleData();
  const sh = shopify.sampleData();
  return {
    files: [
      { name: "ebay-transaction-report.csv", text: e.report },
      { name: "etsy-payment-account-statement.csv", text: t.statement },
      { name: "poshmark-my-sales-report.csv", text: poshmark.sampleCsv() },
      { name: "whatnot-orders.csv", text: whatnot.sampleCsv() },
      { name: "shopify-payments-transactions.csv", text: sh.transactions },
      { name: "shopify-orders.csv", text: sh.orders },
    ],
    costs: e.costs + "\n" + sh.costs.split("\n").slice(1).join("\n"),
  };
}

export const money = (v) => (v === null || v === undefined ? "–" : (v < 0 ? "-" : "") + Math.abs(v).toLocaleString("en-US", { style: "currency", currency: "USD" }));
export const decodeBuffer = poshmark.decodeBuffer;

engines/ebay.mjs.text:
// eBay seller analysis from one CSV the seller already has: the Transaction
// report (Seller Hub -> Reports -> Downloads). Every order line carries its
// item, its fees and its net; shipping labels, refunds and Promoted Listings
// charges are separate rows joined back by order number. Output is the fee
// waterfall, profit per item after cost of goods, and plain-language
// findings. Pure functions, no DOM, no network.

const ALIASES = {
  date: ["transaction creation date", "date", "transaction date"],
  type: ["type", "transaction type"],
  orderId: ["order number", "order id", "order #"],
  legacyOrderId: ["legacy order id"],
  net: ["net amount", "net"],
  itemId: ["item id", "item number"],
  title: ["item title", "title", "description"],
  description: ["description"],
  label: ["custom label", "custom label (sku)", "sku"],
  quantity: ["quantity"],
  subtotal: ["item subtotal", "item price"],
  shipping: ["shipping and handling", "shipping & handling", "postage and packaging"],
  fvfFixed: ["final value fee - fixed", "final value fee – fixed", "final value fee fixed"],
  fvfVariable: ["final value fee - variable", "final value fee – variable", "final value fee variable"],
  notAsDescribed: ["very high \"not as described\" fee", "very high 'not as described' fee", "very high not as described fee"],
  belowStandard: ["below standard performance fee"],
  international: ["international fee"],
  depositProcessing: ["deposit processing fee"],
  gross: ["gross transaction amount"],
};

export function parseCsv(text) {
  const rows = [];
  let row = [], field = "", quoted = false;
  const src = String(text ?? "").replace(/^﻿/, "");
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') { if (src[i + 1] === '"') { field += '"'; i++; } else quoted = false; }
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((f) => f.trim() !== "")) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((f) => f.trim() !== "")) rows.push(row);
  return rows;
}

const MONTHS = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };

// eBay writes "Sep 1, 2026", "Sep 01, 2026", "1 Sep 2026", ISO or US slashes.
export function parseDate(value) {
  const s = String(value ?? "").trim();
  if (!s) return null;
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { y: +m[1], mo: +m[2] - 1, d: +m[3] };
  m = s.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})/);
  if (m && MONTHS[m[1].toLowerCase()] !== undefined) return { y: +m[3], mo: MONTHS[m[1].toLowerCase()], d: +m[2] };
  m = s.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})/);
  if (m && MONTHS[m[2].toLowerCase()] !== undefined) return { y: +m[3], mo: MONTHS[m[2].toLowerCase()], d: +m[1] };
  m = s.match(/^(\d{1,2})[/.](\d{1,2})[/.](\d{4})/);
  if (m) return { y: +m[3], mo: +m[1] - 1, d: +m[2] };
  return null;
}
const monthKeyOf = (p) => `${p.y}-${String(p.mo + 1).padStart(2, "0")}`;

// "--" and "" are how eBay writes "nothing here"; both are zero, not errors.
export function parseMoney(value) {
  let s = String(value ?? "").trim();
  if (!s || /^-+$/.test(s)) return 0;
  let neg = false;
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
  if (/^\s*-/.test(s)) neg = true;
  s = s.replace(/[^0-9.,]/g, "");
  if (s.includes(",") && s.includes(".")) {
    s = s.lastIndexOf(",") > s.lastIndexOf(".") ? s.replace(/\./g, "").replace(",", ".") : s.replace(/,/g, "");
  } else if (s.includes(",")) {
    s = /,\d{1,2}$/.test(s) ? s.replace(",", ".") : s.replace(/,/g, "");
  }
  const n = parseFloat(s);
  if (Number.isNaN(n)) return NaN;
  return neg ? -n : n;
}

function findColumns(header) {
  const norm = header.map((h) => h.trim().toLowerCase().replace(/[“”]/g, '"'));
  const cols = {};
  for (const [field, names] of Object.entries(ALIASES)) {
    for (const n of names) {
      const at = norm.indexOf(n);
      if (at !== -1) { cols[field] = at; break; }
    }
  }
  // "Description" is both the free-text reason on fee rows and, in older
  // exports, the item title: only treat it as the title when there is no
  // "Item title" column, and always keep it as the description.
  const d = norm.indexOf("description");
  if (d !== -1) cols.description = d;
  return cols;
}

// The report starts with a few lines of metadata (report name, seller,
// date range) before the header, so find the header instead of assuming row 0.
function headerRowIndex(table) {
  for (let i = 0; i < Math.min(table.length, 30); i++) {
    const norm = table[i].map((h) => h.trim().toLowerCase());
    if (norm.includes("type") && norm.includes("net amount") && (norm.includes("order number") || norm.includes("item id"))) return i;
  }
  return -1;
}

// One row per money movement. `net` is signed from the seller's point of view.
export function normalizeReport(table) {
  if (!table.length) return { rows: [], skipped: [], error: "The file is empty." };
  const h = headerRowIndex(table);
  if (h === -1) return { rows: [], skipped: [], error: "No header row found. Expected the Transaction report from Seller Hub (Reports → Downloads) with columns like “Type”, “Order number”, “Net amount”, “Item title” and “Final Value Fee - fixed”." };
  const cols = findColumns(table[h]);
  if (cols.date === undefined) return { rows: [], skipped: [], error: "No “Transaction creation date” column found." };
  const get = (r, f) => (cols[f] === undefined ? "" : (r[cols[f]] ?? "")).trim();
  const rows = [], skipped = [];
  for (let i = h + 1; i < table.length; i++) {
    const r = table[i];
    const line = i + 1;
    if (r.length < 3) continue; // trailing summary lines
    const date = parseDate(get(r, "date"));
    if (!date) { skipped.push({ line, reason: `unreadable date “${get(r, "date")}”` }); continue; }
    const num = (f) => parseMoney(get(r, f));
    const vals = { net: num("net"), subtotal: num("subtotal"), shipping: num("shipping"), fvfFixed: num("fvfFixed"), fvfVariable: num("fvfVariable"), notAsDescribed: num("notAsDescribed"), belowStandard: num("belowStandard"), international: num("international"), depositProcessing: num("depositProcessing") };
    if (Object.values(vals).some(Number.isNaN)) { skipped.push({ line, reason: "unreadable amount" }); continue; }
    const type = get(r, "type");
    const qty = parseInt(get(r, "quantity"), 10);
    rows.push({
      line, date, month: monthKeyOf(date), type, typeKey: type.toLowerCase(),
      orderId: get(r, "orderId") || get(r, "legacyOrderId"),
      itemId: get(r, "itemId"),
      title: cols.title !== undefined && cols.title !== cols.description ? get(r, "title") : "",
      description: get(r, "description"), label: get(r, "label"),
      quantity: Number.isNaN(qty) ? 1 : Math.max(1, qty),
      ...vals,
    });
  }
  return { rows, skipped, error: null };
}

const round2 = (n) => Math.round(n * 100) / 100;

// Every row lands in exactly one bucket. Ads are checked before the generic
// "fee" wording so "Promoted Listings - General fee" is not an "other fee".
export function classify(r) {
  const t = r.typeKey, d = r.description.toLowerCase();
  if (/^(payout|transfer|hold|release|payment to|withdrawal)/.test(t)) return "payout";
  if (t === "order" || t === "sale") return "sale";
  if (t === "refund" || /^refund/.test(d) && t !== "other fee") return "refund";
  if (t === "shipping label" || /shipping label|postage/.test(t)) return "labels";
  if (/^(claim|dispute)|payment dispute|chargeback|case/.test(t)) return "disputes";
  if (/promoted listing|promoted offsite|ad fee|advertis/.test(d)) return "ads";
  if (/insertion|listing fee|listing upgrade/.test(d)) return "listing";
  if (/store subscription|subscription/.test(d)) return "subscription";
  if (/international/.test(d)) return "international";
  if (/not as described|below standard|performance/.test(d)) return "penalty";
  if (/credit|reversal|adjust/.test(d) || t === "credit") return "credit";
  if (/fee|charge/.test(t) || /fee|charge/.test(d)) return "otherfee";
  return "other";
}

const FEE_BUCKETS = ["fvf", "international", "penalty", "depositfee", "ads", "listing", "subscription", "otherfee", "disputes", "labels", "credit", "other"];

const keyOf = (r) => r.itemId || r.title || "(unknown item)";

// costs: { [item title | custom label | item id]: unitCost }
export function analyze(rows, { costs = {}, returnsResellable = true } = {}) {
  if (!rows.length) return { invalid: "No usable transaction rows." };
  const buckets = { sale: 0, shippingCharged: 0, refund: 0, adjustments: 0 };
  for (const b of FEE_BUCKETS) buckets[b] = 0;
  const counts = {};
  const months = new Map();
  const orders = new Map();
  let payouts = 0;

  const month = (k) => {
    if (!months.has(k)) months.set(k, { key: k, sales: 0, fees: 0, refunds: 0, net: 0 });
    return months.get(k);
  };
  const order = (id) => {
    if (!orders.has(id)) orders.set(id, { id, lines: [], sale: 0, saleNet: 0, refund: 0, labels: 0, ads: 0, otherCosts: 0, net: 0 });
    return orders.get(id);
  };

  for (const r of rows) {
    const cat = classify(r);
    counts[cat] = (counts[cat] || 0) + 1;
    if (cat === "payout") { payouts += Math.abs(r.net); continue; }
    const m = month(r.month);
    m.net += r.net;
    const o = r.orderId ? order(r.orderId) : null;
    if (o) o.net += r.net;

    if (cat === "sale") {
      // Buyer-paid amount is item + shipping. Each fee column is a cost
      // whatever sign the export gives it; anything the columns do not
      // explain (seller-collected tax, currency rounding) is "adjustments",
      // so the waterfall always ties back to the Net amount column.
      const gross = r.subtotal + r.shipping;
      const fvf = -(Math.abs(r.fvfFixed) + Math.abs(r.fvfVariable));
      const intl = -Math.abs(r.international);
      const pen = -(Math.abs(r.notAsDescribed) + Math.abs(r.belowStandard));
      const dep = -Math.abs(r.depositProcessing);
      const explained = gross + fvf + intl + pen + dep;
      buckets.sale += r.subtotal;
      buckets.shippingCharged += r.shipping;
      buckets.fvf += fvf; buckets.international += intl; buckets.penalty += pen; buckets.depositfee += dep;
      buckets.adjustments += r.net - explained;
      const fees = fvf + intl + pen + dep;
      m.sales += gross; m.fees += fees;
      if (o) {
        o.sale += gross; o.saleNet += r.net;
        o.lines.push({ key: keyOf(r), title: r.title || r.description || r.itemId || "(unknown item)", itemId: r.itemId, label: r.label, qty: r.quantity, revenue: r.subtotal, gross, net: r.net });
      }
    } else if (cat === "refund") {
      buckets.refund += r.net; m.refunds += r.net;
      if (o) o.refund += r.net;
    } else if (cat === "labels") {
      buckets.labels += r.net;
      if (o) o.labels += r.net;
    } else {
      buckets[cat] = (buckets[cat] ?? 0) + r.net;
      m.fees += r.net;
      if (o && cat === "ads") o.ads += r.net;
      else if (o) o.otherCosts += r.net;
    }
  }

  const sales = buckets.sale + buckets.shippingCharged;
  const feeBuckets = {};
  let feeTotal = 0;
  for (const b of FEE_BUCKETS) { feeBuckets[b] = buckets[b]; feeTotal += buckets[b]; }
  // Labels are what the buyer's shipping payment buys, so they stay out of
  // the take rate that measures what eBay itself keeps.
  const platformFees = feeTotal - feeBuckets.labels - feeBuckets.disputes;
  const operating = buckets.sale + buckets.shippingCharged + buckets.refund + feeTotal + buckets.adjustments;

  // ---- per item ----
  const items = new Map();
  const item = (l) => {
    if (!items.has(l.key)) items.set(l.key, { key: l.key, name: l.title, itemId: l.itemId, label: l.label, units: 0, unitsRefunded: 0, orders: 0, revenue: 0, gross: 0, costs: 0, refunds: 0, ads: 0, labels: 0, net: 0 });
    return items.get(l.key);
  };
  let attributedNet = 0;
  for (const o of orders.values()) {
    if (!o.lines.length) continue;
    const total = o.lines.reduce((a, l) => a + l.gross, 0);
    // Refund rows usually carry the fee credit back, so compare refund to what
    // the sale paid out (its net), not to what the buyer paid.
    const fullyRefunded = o.saleNet > 0 && -o.refund >= o.saleNet * 0.95;
    for (const l of o.lines) {
      const share = total > 0 ? l.gross / total : 1 / o.lines.length;
      const it = item(l);
      it.units += l.qty; it.orders += 1; it.revenue += l.revenue; it.gross += l.gross;
      it.refunds += o.refund * share; it.ads += o.ads * share; it.labels += o.labels * share;
      // Everything the order caused: its own net, the label, refund and any
      // ad or other charge carrying its order number.
      const net = l.net + (o.labels + o.refund + o.ads + o.otherCosts) * share;
      it.net += net;
      attributedNet += net;
      if (fullyRefunded) it.unitsRefunded += l.qty;
    }
  }
  const costFor = (it) => {
    for (const k of [it.name, it.label, it.itemId, it.key]) if (k && typeof costs[k] === "number" && !Number.isNaN(costs[k])) return costs[k];
    return null;
  };
  const itemList = [...items.values()].map((it) => {
    const netUnits = it.units - it.unitsRefunded;
    const cost = costFor(it);
    const costed = returnsResellable ? Math.max(0, netUnits) : it.units;
    const cogs = cost === null ? null : cost * costed;
    return {
      ...it, netUnits, refundRate: it.units ? it.unitsRefunded / it.units : 0,
      avgPrice: it.units ? it.revenue / it.units : 0,
      cogs, profit: cogs === null ? null : it.net - cogs,
      profitPerUnit: cogs !== null && netUnits > 0 ? (it.net - cogs) / netUnits : null,
      margin: cogs !== null && it.gross ? (it.net - cogs) / it.gross : null,
    };
  }).sort((a, b) => b.gross - a.gross);

  const orderCount = [...orders.values()].filter((o) => o.sale > 0).length;
  const monthList = [...months.values()].sort((a, b) => a.key.localeCompare(b.key));
  const cogsTotal = itemList.reduce((a, x) => a + (x.cogs ?? 0), 0);
  const anyCosted = itemList.some((x) => x.profit !== null);
  const allCosted = itemList.length > 0 && itemList.every((x) => x.profit !== null);
  const shippingGap = buckets.shippingCharged + buckets.labels; // charged minus label spend (labels are negative)

  const summary = {
    firstMonth: monthList[0]?.key ?? "", lastMonth: monthList[monthList.length - 1]?.key ?? "",
    sales, itemSales: buckets.sale, shippingCharged: buckets.shippingCharged, refunds: buckets.refund,
    feeBuckets, feeTotal, platformFees, operating, payouts, adjustments: buckets.adjustments, counts, orderCount,
    takeRate: sales ? -platformFees / sales : 0,
    adRate: sales ? -buckets.ads / sales : 0,
    refundRate: sales ? -buckets.refund / sales : 0,
    avgOrder: orderCount ? sales / orderCount : 0,
    shippingGap, labelSpend: -buckets.labels,
    itemCount: itemList.length, attributedNet, shopLevel: operating - attributedNet, cogsTotal, anyCosted, allCosted,
    profit: anyCosted ? operating - cogsTotal : null,
  };
  return { summary, items: itemList, months: monthList, findings: findings(summary, itemList, monthList) };
}

const $ = (n) => (n < 0 ? "-$" : "$") + Math.abs(Math.round(n)).toLocaleString("en-US");
const P = (x, d = 1) => (x * 100).toFixed(d) + "%";

function findings(s, list, months) {
  const out = [];
  const add = (severity, title, detail) => out.push({ severity, title, detail });
  const fb = s.feeBuckets;

  if (s.sales > 0) {
    add(s.takeRate > 0.18 ? "medium" : "info", `eBay kept ${P(s.takeRate)} of what buyers paid`,
      `${$(-s.platformFees)} of fees and ads against ${$(s.sales)} of item and shipping revenue (shipping labels, ${$(-fb.labels)}, are separate because the buyer's shipping payment covers them). Final value fees ${$(-fb.fvf)}, Promoted Listings ${$(-fb.ads)}, international ${$(-fb.international)}, listing and subscription ${$(-(fb.listing + fb.subscription))}. eBay charges its final value fee on the shipping and tax you collect as well as the item price, which is why the rate is above the headline category percentage.`);
  }

  if (s.shippingCharged > 0 || s.labelSpend > 0) {
    if (s.shippingGap < -Math.max(20, s.sales * 0.01)) {
      add(s.shippingGap < -s.sales * 0.03 ? "high" : "medium", `Shipping cost you ${$(-s.shippingGap)} more than buyers paid`,
        `Buyers paid ${$(s.shippingCharged)} for shipping and labels bought through eBay cost ${$(s.labelSpend)}. Free shipping is a pricing choice, but it should be built into the item price on purpose. Check weight and package size on the items with the biggest gap.`);
    } else if (s.shippingGap > Math.max(20, s.sales * 0.01)) {
      add("info", `Shipping paid for itself with ${$(s.shippingGap)} to spare`,
        `Buyers paid ${$(s.shippingCharged)} and labels cost ${$(s.labelSpend)}. Labels bought outside eBay (pirate-style third-party postage) are not in this file, so the surplus may be smaller than it looks.`);
    }
  }

  if (s.adRate > 0.03) {
    add(s.adRate > 0.08 ? "high" : "medium", `Promoted Listings cost ${P(s.adRate)} of sales (${$(-fb.ads)})`,
      `${s.counts.ads || 0} ad charge${s.counts.ads === 1 ? "" : "s"}. General-campaign fees apply to the whole sale price when a buyer clicks a promoted listing and buys within 30 days, including sales that would have happened anyway. Compare the ad rate to your margin on the items promoted, and lower the ad rate or end campaigns on thin-margin items.`);
  }

  if (s.refundRate > 0.05) {
    add(s.refundRate > 0.1 ? "high" : "medium", `Refunds are ${P(s.refundRate)} of revenue`,
      `${$(-s.refunds)} refunded. eBay refunds the fixed per-order fee only in some cases, and the outbound label is already spent, so a returned order costs more than the margin it removes. Open the returns reasons and fix the listing description or packaging behind the top ones.`);
  }

  if ((fb.penalty ?? 0) < 0) {
    add("high", `${$(-fb.penalty)} of performance fees`,
      "“Very high not as described” or “below standard” fees are charged on top of the normal final value fee when defect rates pass eBay's thresholds. They are the most avoidable fee in the report; look at Seller Hub → Performance to see which defects triggered them.");
  }

  if ((fb.disputes ?? 0) < -1) {
    add("medium", `${$(-fb.disputes)} in disputes, claims and chargebacks`, "Rows typed Claim or Dispute in the report. Keep proof of delivery and package photos for any item that draws one.");
  }

  if (fb.international < 0 && s.sales > 0 && -fb.international / s.sales > 0.01) {
    add("medium", `International fees are ${P(-fb.international / s.sales)} of sales`,
      `${$(-fb.international)} charged on orders shipping to buyers outside your country. If your international items have thin margins, add the fee to the item price or turn off international shipping for them.`);
  }

  const losers = list.filter((x) => x.profit !== null && x.profit < 0 && x.units >= 2);
  if (losers.length) {
    const worst = [...losers].sort((a, b) => a.profit - b.profit).slice(0, 3);
    add("high", `${losers.length} item${losers.length > 1 ? "s" : ""} lose money after cost of goods`,
      `Worst: ${worst.map((x) => `${x.name} (${$(x.profit)} on ${x.units} units)`).join("; ")}. Raise the price, cut the cost, or stop promoting them.`);
  }

  const thin = list.filter((x) => x.margin !== null && x.margin >= 0 && x.margin < 0.15 && x.units >= 5);
  if (thin.length) {
    add("medium", `${thin.length} item${thin.length > 1 ? "s" : ""} earn under 15% after cost of goods`,
      `${thin.slice(0, 4).map((x) => `${x.name} ${P(x.margin)}`).join("; ")}. Your time is not in the cost figure, so a thin margin here is thinner than it looks.`);
  }

  const refunded = list.filter((x) => x.units >= 5 && x.refundRate >= 0.1).sort((a, b) => b.refundRate - a.refundRate);
  if (refunded.length) {
    add("high", `${refunded.length} item${refunded.length > 1 ? "s" : ""} with 10%+ of units in fully refunded orders`,
      `${refunded.slice(0, 4).map((x) => `${x.name} ${P(x.refundRate)}`).join("; ")}.`);
  }

  const cheap = list.filter((x) => x.orders >= 5 && x.avgPrice > 0 && x.avgPrice < 12);
  if (cheap.length) {
    add("info", `${cheap.length} low-priced item${cheap.length > 1 ? "s" : ""} carry the per-order fee heavily`,
      `${cheap.slice(0, 3).map((x) => `${x.name} (${$(x.avgPrice)} average)`).join("; ")}. eBay adds a fixed fee of $0.30 to $0.40 to every order, which is 3% to 4% of a $10 item on top of the percentage. Bundling or multi-buy offers spread it.`);
  }

  if (months.length >= 4) {
    const rate = (m) => (m.sales ? -m.fees / m.sales : null);
    const first = months.slice(0, 2).map(rate).filter((x) => x !== null);
    const last = months.slice(-2).map(rate).filter((x) => x !== null);
    if (first.length && last.length) {
      const a = first.reduce((x, y) => x + y) / first.length, b = last.reduce((x, y) => x + y) / last.length;
      if (b - a > 0.03) add("medium", `Fees rose from ${P(a)} to ${P(b)} of sales`,
        `Comparing the first two and last two months. That is ${P(b - a)} of every sale gone to more promotion, more international orders or fee changes. If prices did not move with it, margin fell by the same amount.`);
    }
  }

  const costed = list.filter((x) => x.profit !== null);
  if (costed.length >= 4) {
    const total = costed.reduce((a, x) => a + Math.max(0, x.profit), 0);
    const top = [...costed].sort((a, b) => b.profit - a.profit)[0];
    if (total > 0 && top.profit / total > 0.6) {
      add("medium", `${top.name} earns ${P(top.profit / total)} of your item profit`,
        "One item carrying most of the profit is a risk: a supplier problem, a policy change or a competing listing hits the whole store. Worth sourcing a second earner.");
    }
  }

  if (s.itemCount > 0 && !s.anyCosted) {
    add("info", "Enter your unit costs to see real profit",
      "What you paid for the item is not in the Transaction report. Type a cost per unit next to each item (or paste title,cost lines, custom label or item number work too) and profit, margin and loss-maker findings appear.");
  } else if (s.itemCount > 0 && !s.allCosted) {
    add("info", "Some items have no unit cost yet", "Profit for those items is left out rather than counted as free.");
  }

  const order = { high: 0, medium: 1, info: 2 };
  return out.sort((a, b) => order[a.severity] - order[b.severity]);
}

export function parseCosts(text) {
  const costs = {};
  const bad = [];
  String(text ?? "").split(/\r?\n/).forEach((line, i) => {
    if (!line.trim()) return;
    const cells = parseCsv(line)[0] || [];
    if (cells.length < 2) { bad.push(i + 1); return; }
    const v = parseMoney(cells[cells.length - 1]);
    const k = cells.slice(0, -1).join(",").trim();
    if (!k || Number.isNaN(v) || v < 0) { if (i > 0 || !/^(name|item|title|sku)/i.test(k)) bad.push(i + 1); return; }
    costs[k] = v;
  });
  return { costs, bad };
}

const PRODUCTS = [
  { name: "Vintage Nikon FM2 35mm Film Camera Body", id: "134500000001", sku: "CAM-FM2", price: 219, per: 4, cost: 140, refund: 0.1, ship: 14.5, intl: 0 },
  { name: "LEGO Star Wars 75192 Millennium Falcon Sealed", id: "134500000002", sku: "LEGO-75192", price: 689, per: 2, cost: 610, refund: 0, ship: 0, intl: 0 },
  { name: "Carhartt Detroit Jacket J001 Size L", id: "134500000003", sku: "APP-J001L", price: 64, per: 9, cost: 22, refund: 0.06, ship: 9.4, intl: 0 },
  { name: "Pokemon Card Sleeves 100ct Lot", id: "134500000004", sku: "TCG-SLV", price: 9.5, per: 22, cost: 3.1, refund: 0.03, ship: 4.2, intl: 0 },
];

// Deterministic synthetic store: returns { report, costs } as text, in the
// layout of a Seller Hub Transaction report (metadata lines, then header).
export function sampleData() {
  const head = "Transaction creation date,Type,Order number,Legacy order ID,Buyer username,Buyer name,Ship to city,Ship to province/region/state,Ship to zip,Ship to country,Net amount,Payout currency,Payout date,Payout ID,Payout method,Payout status,Reason for hold,Item ID,Transaction ID,Item title,Custom label,Quantity,Item subtotal,Shipping and handling,Seller collected tax,eBay collected tax,Final Value Fee - fixed,Final Value Fee - variable,\"Very high \"\"not as described\"\" fee\",Below standard performance fee,International fee,Deposit processing fee,Gross transaction amount,Transaction currency,Exchange rate,Reference ID,Description";
  const out = ["Transaction report", "Seller ID,samplestore", "Report period,\"Jun 1, 2026 - Sep 30, 2026\"", "", head];
  const q = (s) => `"${String(s).replace(/"/g, '""')}"`;
  const m = (n) => (n < 0 ? "-" : "") + Math.abs(n).toFixed(2);
  const row = (o) => {
    const c = new Array(37).fill("--");
    const set = (name, v) => { c[head.split(",").indexOf(name)] = v; };
    set("Transaction creation date", q(o.date)); set("Type", o.type); set("Order number", o.oid ?? "--");
    set("Net amount", m(o.net)); set("Item ID", o.id ?? "--"); set("Item title", o.title ? q(o.title) : "--");
    set("Custom label", o.sku ?? "--"); set("Quantity", o.qty ?? "--");
    set("Item subtotal", o.sub !== undefined ? m(o.sub) : "--"); set("Shipping and handling", o.ship !== undefined ? m(o.ship) : "--");
    set("Final Value Fee - fixed", o.fixed !== undefined ? m(-o.fixed) : "--"); set("Final Value Fee - variable", o.var !== undefined ? m(-o.var) : "--");
    set("Description", o.desc ? q(o.desc) : "--");
    out.push(c.join(","));
  };
  const names = ["Jun", "Jul", "Aug", "Sep"];
  let n = 0;
  names.forEach((mn, mi) => {
    PRODUCTS.forEach((p, pi) => {
      const count = Math.round(p.per * (1 + mi * 0.1));
      for (let i = 0; i < count; i++) {
        n++;
        const day = 1 + ((i * 3 + pi + mi) % 27);
        const date = `${mn} ${day}, 2026`;
        const oid = `27-${String(10000 + n * 7).padStart(5, "0")}-${String(50000 + n * 3)}`;
        const gross = p.price + p.ship;
        const fixed = gross > 10 ? 0.4 : 0.3;
        const variable = round2(gross * 0.1325);
        const net = round2(gross - fixed - variable);
        row({ date, type: "Order", oid, id: p.id, title: p.name, sku: p.sku, qty: 1, sub: p.price, ship: p.ship, fixed, var: variable, net });
        if (p.ship) row({ date, type: "Shipping label", oid, net: -round2(p.ship * (pi === 2 ? 1.35 : 1.05)), desc: "Shipping label" });
        if ((i + pi) % 4 === 0) row({ date, type: "Other fee", oid, id: p.id, net: -round2(p.price * 0.05), desc: "Promoted Listings - General fee" });
        if (i > 0 && p.refund && (i + mi * 2) % Math.round(1 / p.refund) === 0) row({ date, type: "Refund", oid, id: p.id, net: -round2(net), desc: "Refund" });
      }
    });
    row({ date: `${mn} 15, 2026`, type: "Other fee", net: -(4.95 + mi), desc: "Insertion fee" });
    row({ date: `${mn} 28, 2026`, type: "Payout", net: -500, desc: "Payout" });
  });
  const costs = PRODUCTS.map((p) => `${p.name},${p.cost.toFixed(2)}`);
  return { report: out.join("\n"), costs: "item,cost\n" + costs.join("\n") };
}

