engines/poshmark.mjs.text:
// Per-item, per-brand and per-month profit analysis from a Poshmark "My Sales
// Report" CSV. Column names are matched by alias from memory of Poshmark's
// export; no real export was available when this was written. Pure functions,
// no DOM, no network.
//
// The fee constants and commissionFor() are the same rules as
// ../poshmark-fee-calculator/calc.mjs (a test asserts the two stay equal):
// a flat $2.95 under $15.00, 20% of the sale price at $15.00 or more.

export const COMMISSION_THRESHOLD = 15;
export const FLAT_FEE = 2.95;
export const PERCENT_RATE = 20;
/** The sale price at which 20% of the price equals the flat fee. */
export const BREAK_EVEN_PRICE = Math.round((FLAT_FEE / (PERCENT_RATE / 100)) * 100) / 100;

export function commissionFor(salePrice) {
  if (salePrice < COMMISSION_THRESHOLD) return { tier: "flat", commission: Math.min(FLAT_FEE, salePrice) };
  return { tier: "percent", commission: salePrice * (PERCENT_RATE / 100) };
}

const ALIASES = {
  id: ["order id", "order #", "order number", "order no", "order", "id", "sale id", "transaction id"],
  date: ["order date", "sale date", "date sold", "sold date", "date of sale", "sold on", "order placed", "date", "order date/time", "sold at"],
  listed: ["listed date", "listing date", "date listed", "list date", "listed on", "created date", "created at", "date created", "listed at"],
  title: ["listing title", "title", "item title", "item name", "item", "listing name", "name", "description", "listing"],
  brand: ["brand", "designer", "brand name", "item brand"],
  sku: ["sku", "custom sku", "item sku", "seller sku", "listing sku", "custom label"],
  listPrice: ["listing price", "list price", "listed price", "original price", "original listing price", "asking price"],
  price: ["order price", "sale price", "sold price", "price", "item price", "order subtotal", "subtotal", "order total", "total sales", "sales", "gross", "item sale price"],
  fee: ["poshmark fee", "posh fee", "poshmark fees", "seller fee", "selling fee", "transaction fee", "commission", "fee", "fees", "marketplace fee"],
  net: ["net earnings", "seller earnings", "your earnings", "earnings", "net payout", "payout", "net proceeds", "proceeds", "net", "seller payout"],
  shipDisc: ["seller shipping discount", "shipping discount", "seller shipping discount amount", "shipping discount (seller)", "seller paid shipping", "seller-paid shipping", "shipping subsidy", "shipping discount amount"],
  cost: ["cost", "item cost", "cost basis", "purchase price", "cogs", "my cost", "cost of goods", "cost of goods sold", "sourcing cost", "cost price", "buy price", "paid"],
  status: ["order status", "status", "state", "sale status"],
  currency: ["currency"],
};

export function parseNumber(v, decimalComma = false) {
  let s = String(v ?? "").trim();
  if (s === "" || /^[-–—\s]+$/.test(s)) return 0;
  const neg = /^\(.*\)$/.test(s) || /^[-−]/.test(s);
  s = s.replace(/[^0-9.,]/g, "");
  s = decimalComma ? s.replace(/\./g, "").replace(",", ".") : s.replace(/,/g, "");
  const n = Number(s);
  if (!s || !Number.isFinite(n)) return NaN;
  return neg ? -n : n;
}

export function decodeBuffer(buf) {
  const u8 = new Uint8Array(buf);
  if (u8[0] === 0xff && u8[1] === 0xfe) return new TextDecoder("utf-16le").decode(u8);
  if (u8[0] === 0xfe && u8[1] === 0xff) return new TextDecoder("utf-16be").decode(u8);
  return new TextDecoder("utf-8").decode(u8);
}

export function detectDelimiter(text) {
  const head = String(text ?? "").split(/\r?\n/).filter((l) => l.trim()).slice(0, 8).join("\n");
  const n = (c) => head.split(c).length - 1;
  const best = [["\t", n("\t")], [";", n(";")], [",", n(",")]].sort((a, b) => b[1] - a[1])[0];
  return best[1] > 0 ? best[0] : ",";
}

export function parseCsv(text, delim = ",") {
  const rows = [];
  let row = [], field = "", quoted = false;
  const src = String(text ?? "").replace(/^﻿/, "");
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') { if (src[i + 1] === '"') { field += '"'; i++; } else quoted = false; }
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === delim) { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((f) => f.trim() !== "")) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((f) => f.trim() !== "")) rows.push(row);
  return rows;
}

export function parseWhen(v, dmy = false) {
  const s = String(v ?? "").trim();
  if (!s) return null;
  let y, mo, d, rest = "";
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(.*)$/);
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; rest = m[4]; }
  else {
    m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2,4})(.*)$/);
    if (!m) return null;
    const a = +m[1], b = +m[2];
    y = +m[3]; if (y < 100) y += 2000;
    if (dmy) { d = a; mo = b; } else { mo = a; d = b; }
    rest = m[4];
  }
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  let hh = 0, mm = 0, hasTime = false;
  const tm = rest.match(/(\d{1,2}):(\d{2})(?::\d{2})?\s*([ap]\.?m\.?)?/i);
  if (tm) {
    hh = +tm[1]; mm = +tm[2]; hasTime = true;
    const ap = tm[3] ? tm[3][0].toLowerCase() : "";
    if (ap === "p" && hh < 12) hh += 12;
    if (ap === "a" && hh === 12) hh = 0;
    if (hh > 23 || mm > 59) return null;
  }
  const t = Date.UTC(y, mo - 1, d, hh, mm);
  return new Date(t).getUTCDate() === d ? { t, hasTime } : null;
}

export function detectDmy(values) {
  let first = false, second = false;
  for (const v of values) {
    const m = String(v ?? "").trim().match(/^(\d{1,2})[/.-](\d{1,2})[/.-]\d{2,4}/);
    if (!m) continue;
    if (+m[1] > 12) first = true;
    if (+m[2] > 12) second = true;
  }
  return first && !second;
}
function findColumns(header) {
  const norm = header.map((h) => h.trim().toLowerCase());
  const cols = {};
  for (const [field, names] of Object.entries(ALIASES)) {
    for (const n of names) {
      const at = norm.indexOf(n);
      if (at !== -1 && !Object.values(cols).includes(at)) { cols[field] = at; break; }
    }
  }
  return cols;
}

const DAY = 86400000;
export const MIN_BRAND_ITEMS = 3;
export const FEE_MODES = ["auto", "schedule"];
const r2 = (n) => Math.round(n * 100) / 100;
const isBlank = (s) => s === "" || /^[-–—\s]+$/.test(s);
const norm = (s) => String(s ?? "").toLowerCase().replace(/\s+/g, " ").trim();
const usd = (n) => (n < 0 ? "-" : "") + "$" + Math.abs(n).toFixed(2);

// Returns { items, skipped, excludedCount, currency, columns, dmy, feeSource, error }.
// An item is { line, id, title, brand, sku, t, listedT, price, fee, scheduleFee,
// payout, shippingLoss, cost, listPrice } where cost is null when the file does
// not say. feeMode "auto" reads the fee column when there is one and otherwise
// applies the published schedule; "schedule" always applies the schedule.
// Cancelled, returned and refunded orders are left out and counted.
export function normalizeRows(table, { decimalComma = false, feeMode = "auto" } = {}) {
  const empty = { items: [], skipped: [], excludedCount: 0, currency: "", columns: {}, dmy: false, feeSource: "schedule" };
  if (!table.length) return { ...empty, error: "The file is empty." };
  let h = -1;
  for (let i = 0; i < Math.min(table.length, 10); i++) {
    const c = findColumns(table[i]);
    if (c.date !== undefined && c.price !== undefined) { h = i; break; }
  }
  if (h < 0) return { ...empty, error: "No header row found. Expected columns like “Order Date” and “Order Price” (or “Sale Price”), plus ideally “Brand”, “Listing Title”, “Poshmark Fee”, “Net Earnings”, “Listed Date” and a cost column. Download My Sales Report from Poshmark or make a sheet with those headers." };
  const cols = findColumns(table[h]);
  const get = (line, f) => (cols[f] === undefined ? "" : (line[cols[f]] ?? "").trim());
  const dmy = detectDmy(table.slice(h + 1).map((l) => get(l, "date")));
  const feeSource = feeMode !== "schedule" && cols.fee !== undefined ? "column" : "schedule";

  const items = [], skipped = [];
  let currency = "", excludedCount = 0;
  for (let i = h + 1; i < table.length; i++) {
    const line = table[i];
    const lineNo = i + 1;
    if (line.every((x) => !String(x).trim())) continue;
    const first = String(line[0] ?? "").trim().toLowerCase();
    if (/^(total|totals|subtotal|grand total|summary)\b/.test(first)) { skipped.push({ line: lineNo, reason: "total row" }); continue; }
    const when = parseWhen(get(line, "date"), dmy);
    if (!when) { skipped.push({ line: lineNo, reason: "date not readable" }); continue; }
    const price = parseNumber(get(line, "price"), decimalComma);
    if (!Number.isFinite(price)) { skipped.push({ line: lineNo, reason: "price not readable" }); continue; }
    if (!(price > 0)) { skipped.push({ line: lineNo, reason: "no sale price" }); continue; }
    if (/cancel|return|refund|declin|fail/i.test(get(line, "status"))) { excludedCount++; continue; }
    const money = (f) => {
      const raw = get(line, f);
      if (cols[f] === undefined || isBlank(raw)) return null;
      const v = parseNumber(raw, decimalComma);
      return Number.isFinite(v) ? v : null;
    };
    const scheduleFee = r2(commissionFor(price).commission);
    const feeRaw = feeSource === "column" ? money("fee") : null;
    const fee = feeRaw === null ? scheduleFee : r2(Math.abs(feeRaw));
    const shipDisc = Math.abs(money("shipDisc") ?? 0);
    const netFile = money("net");
    const expected = price - fee;
    let payout, shippingLoss;
    if (netFile !== null) {
      // The file's own net is trusted. Anything it takes off beyond the fee is a
      // deduction (a seller shipping discount is the usual one).
      payout = netFile;
      const gap = expected - netFile;
      shippingLoss = Math.max(shipDisc, gap > 0.005 ? gap : 0);
    } else {
      payout = expected - shipDisc;
      shippingLoss = shipDisc;
    }
    const listed = parseWhen(get(line, "listed"), dmy);
    const cur = get(line, "currency");
    if (cur && !currency) currency = cur;
    const cost = money("cost");
    items.push({
      line: lineNo, id: get(line, "id"), title: get(line, "title"), brand: get(line, "brand"), sku: get(line, "sku"),
      t: when.t, listedT: listed ? listed.t : null, price: r2(price), fee, scheduleFee,
      payout: r2(payout), shippingLoss: r2(shippingLoss), cost: cost === null ? null : r2(cost),
      listPrice: money("listPrice"),
    });
  }
  if (!items.length) return { ...empty, skipped, excludedCount, currency, columns: cols, dmy, feeSource, error: "No sales could be read from the file. " + (skipped.length ? `${skipped.length} row(s) were skipped (first: line ${skipped[0].line}, ${skipped[0].reason}).` : "Every order was cancelled, returned or refunded.") };
  return { items, skipped, excludedCount, currency, columns: cols, dmy, feeSource };
}

// Pasted cost basis: one "SKU, cost" pair per line (comma, tab or semicolon; the
// last separator splits, so a title with commas still works). A first line whose
// cost is not a number is treated as a header. Returns { map, count, errors }.
export function parseCostList(text) {
  const map = new Map(), errors = [];
  const lines = String(text ?? "").split(/\r?\n/);
  let count = 0;
  lines.forEach((raw, idx) => {
    const line = raw.trim();
    if (!line) return;
    const at = Math.max(line.lastIndexOf(","), line.lastIndexOf("\t"), line.lastIndexOf(";"));
    if (at <= 0) { errors.push({ line: idx + 1, reason: "needs a name, a separator and a cost" }); return; }
    const key = norm(line.slice(0, at).replace(/^"|"$/g, ""));
    const cost = parseNumber(line.slice(at + 1).replace(/^"|"$/g, ""));
    if (!key || !Number.isFinite(cost) || line.slice(at + 1).trim() === "") {
      if (idx === 0) return;
      errors.push({ line: idx + 1, reason: "cost is not a number" });
      return;
    }
    if (cost < 0) { errors.push({ line: idx + 1, reason: "cost is negative" }); return; }
    map.set(key, cost);
    count++;
  });
  return { map, count, errors };
}

function rollup(label, list) {
  const price = list.reduce((s, x) => s + x.price, 0);
  const fee = list.reduce((s, x) => s + x.fee, 0);
  const payout = list.reduce((s, x) => s + x.payout, 0);
  const costed = list.filter((x) => x.cost !== null);
  const costedPrice = costed.reduce((s, x) => s + x.price, 0);
  const cost = costed.reduce((s, x) => s + x.cost, 0);
  const profit = costed.reduce((s, x) => s + x.profit, 0);
  const days = list.filter((x) => x.daysToSell !== null).map((x) => x.daysToSell);
  return {
    label, items: list.length, price: r2(price), fee: r2(fee), feeRate: price > 0 ? fee / price : null,
    shippingLoss: r2(list.reduce((s, x) => s + x.shippingLoss, 0)), payout: r2(payout),
    costedItems: costed.length, cost: r2(cost), profit: costed.length ? r2(profit) : null,
    margin: costed.length && costedPrice > 0 ? profit / costedPrice : null,
    avgDays: days.length ? days.reduce((s, d) => s + d, 0) / days.length : null,
  };
}

const monthKey = (t) => new Date(t).toISOString().slice(0, 7);
const median = (a) => { const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length ? (s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2) : null; };

// items: normalizeRows(...).items. costList: pasted text (overrides the file's
// cost column for any item it matches, by SKU, then order id, then title).
export function analyze(rawItems, { costList = "", from = null, to = null, minBrandItems = MIN_BRAND_ITEMS } = {}) {
  const parsedList = parseCostList(costList);
  const matchedKeys = new Set();
  let items = rawItems.filter((x) => (from === null || x.t >= from) && (to === null || x.t < to + DAY));
  if (!items.length) return { invalid: "No sales fall inside the date range you chose." };
  items = items.map((x) => {
    let cost = x.cost, costSource = x.cost === null ? null : "file";
    for (const k of [norm(x.sku), norm(x.id), norm(x.title)]) {
      if (k && parsedList.map.has(k)) { cost = r2(parsedList.map.get(k)); costSource = "list"; matchedKeys.add(k); break; }
    }
    const profit = cost === null ? null : r2(x.payout - cost);
    const daysToSell = x.listedT !== null && x.t >= x.listedT ? Math.round((x.t - x.listedT) / DAY) : null;
    return { ...x, cost, costSource, profit, daysToSell, brandLabel: x.brand || "(no brand)", effectiveFeeRate: x.price > 0 ? x.fee / x.price : null };
  });
  const unmatched = [...parsedList.map.keys()].filter((k) => !matchedKeys.has(k));

  const group = (keyFn, sortFn) => {
    const m = new Map();
    for (const x of items) { const k = keyFn(x); (m.get(k) ?? m.set(k, []).get(k)).push(x); }
    return [...m].map(([k, list]) => rollup(k, list)).sort(sortFn);
  };
  const byMonth = group((x) => monthKey(x.t), (a, b) => (a.label < b.label ? -1 : 1));
  const byBrand = group((x) => x.brandLabel, (a, b) => ((b.profit ?? b.payout) - (a.profit ?? a.payout)) || (b.items - a.items));

  const total = rollup("All", items);
  const costed = items.filter((x) => x.cost !== null);
  const rankBasis = costed.length ? "profit" : "payout";
  const rankPool = costed.length ? costed : items;
  const metric = (x) => (rankBasis === "profit" ? x.profit : x.payout);
  const worstItems = [...rankPool].sort((a, b) => metric(a) - metric(b)).slice(0, 10);
  const bestItems = [...rankPool].sort((a, b) => metric(b) - metric(a)).slice(0, 10);
  const losing = costed.filter((x) => x.profit < 0);

  const flat = items.filter((x) => x.scheduleFee > 0 && x.price < COMMISSION_THRESHOLD);
  const flatExtra = r2(flat.reduce((s, x) => s + Math.max(0, x.scheduleFee - x.price * (PERCENT_RATE / 100)), 0));
  const feeMismatch = items.filter((x) => Math.abs(x.fee - x.scheduleFee) > 0.02);
  const shipLossItems = items.filter((x) => x.shippingLoss > 0.005);
  const days = items.filter((x) => x.daysToSell !== null).map((x) => x.daysToSell);
  const slow = items.filter((x) => x.daysToSell !== null && x.daysToSell > 90);

  // Brands to stop sourcing: with costs, a brand that lost money over at least
  // minBrandItems costed sales. Without any costs the file cannot say, so the
  // fallback names brands where the fee alone takes a quarter of the price.
  const stopBrands = byBrand.filter((b) => b.costedItems >= minBrandItems && b.profit < 0);
  const thinBrands = byBrand.filter((b) => b.costedItems >= minBrandItems && b.profit >= 0 && b.margin !== null && b.margin < 0.1);
  const feeHeavyBrands = costed.length ? [] : byBrand.filter((b) => b.items >= minBrandItems && b.feeRate >= 0.25);

  const findings = [];
  if (!costed.length) findings.push({ severity: "high", title: "No cost basis, so nothing here is profit yet", detail: "Payout below is sale price minus Poshmark's fee (and any shipping deduction), before what you paid for the item. Add a cost column to the file or paste SKU,cost pairs in step 2 to see profit, losing items and brands to stop sourcing." });
  else if (costed.length < items.length) findings.push({ severity: "medium", title: `${items.length - costed.length} of ${items.length} sales have no cost`, detail: `Profit, margin and the brand verdicts use only the ${costed.length} sales with a cost. Payout totals cover all ${items.length}.` });
  if (losing.length) findings.push({ severity: "high", title: `${losing.length} sale${losing.length === 1 ? "" : "s"} lost money after fee and cost`, detail: `Together ${usd(losing.reduce((s, x) => s + x.profit, 0))}. The worst are listed below.` });
  if (stopBrands.length) findings.push({ severity: "high", title: `Consider not sourcing: ${stopBrands.map((b) => b.label).join(", ")}`, detail: stopBrands.map((b) => `${b.label}: ${usd(b.profit)} over ${b.costedItems} sales (${(b.feeRate * 100).toFixed(0)}% effective fee)`).join("; ") + `. A brand needs at least ${minBrandItems} costed sales to be named.` });
  if (thinBrands.length) findings.push({ severity: "medium", title: `Thin margin brands: ${thinBrands.map((b) => b.label).join(", ")}`, detail: thinBrands.map((b) => `${b.label}: ${(b.margin * 100).toFixed(0)}% of sale price kept as profit`).join("; ") + "." });
  if (feeHeavyBrands.length) findings.push({ severity: "medium", title: `Fee takes 25% or more of the price: ${feeHeavyBrands.map((b) => b.label).join(", ")}`, detail: "The flat fee is heavy on low-priced items. Without a cost column this is the only sourcing signal the file can give." });
  if (flat.length) findings.push({ severity: flatExtra > 0 ? "medium" : "info", title: `${flat.length} sale${flat.length === 1 ? "" : "s"} under $15 paid the flat $2.95`, detail: `That is ${usd(flat.reduce((s, x) => s + x.scheduleFee, 0))} in fees on ${usd(flat.reduce((s, x) => s + x.price, 0))} of sales (${(flat.reduce((s, x) => s + x.scheduleFee, 0) / flat.reduce((s, x) => s + x.price, 0) * 100).toFixed(0)}%)${flatExtra > 0 ? `, ${usd(flatExtra)} more than 20% would have taken, because the flat fee costs more than 20% below $${BREAK_EVEN_PRICE.toFixed(2)}` : ""}.` });
  if (shipLossItems.length) findings.push({ severity: "medium", title: `${shipLossItems.length} sale${shipLossItems.length === 1 ? "" : "s"} carried a shipping discount or deduction`, detail: `${usd(shipLossItems.reduce((s, x) => s + x.shippingLoss, 0))} in total, an average of ${usd(shipLossItems.reduce((s, x) => s + x.shippingLoss, 0) / shipLossItems.length)} on those sales. Where the file lists a seller shipping discount it is used; otherwise any gap between price minus fee and net earnings is counted.` });
  if (feeMismatch.length) findings.push({ severity: "info", title: `${feeMismatch.length} fee${feeMismatch.length === 1 ? "" : "s"} in the file differ from the published $2.95 / 20% schedule`, detail: "The fee in your file is used. Promotions, a different rate on your account or an old schedule can explain this; check a few against your own statement." });
  if (slow.length) findings.push({ severity: "info", title: `${slow.length} item${slow.length === 1 ? "" : "s"} took more than 90 days to sell`, detail: "Slow sellers tie up cash and closet space. Days are from the listed date to the order date in the file." });

  return {
    items, byBrand, byMonth, worstItems, bestItems, rankBasis, findings, stopBrands, thinBrands, unmatched, costList: { count: parsedList.count, errors: parsedList.errors },
    summary: {
      ...total, from: Math.min(...items.map((x) => x.t)), to: Math.max(...items.map((x) => x.t)), brands: byBrand.length,
      losingItems: losing.length, flatItems: flat.length, flatExtraVs20: flatExtra, shippingLossItems: shipLossItems.length,
      feeMismatches: feeMismatch.length, avgDays: days.length ? days.reduce((s, d) => s + d, 0) / days.length : null, medianDays: median(days), daysItems: days.length,
    },
  };
}

// Plain text for pasting into a note, a forum post or a message to yourself.
export function summaryText(r, { currency = "" } = {}) {
  const s = r.summary, c = currency ? currency + " " : "";
  const m = (n) => (Number.isFinite(n) ? (n < 0 ? "-" : "") + c + "$" + Math.abs(n).toFixed(2) : "n/a");
  const lines = [
    `Poshmark sales ${dateStr(s.from)} to ${dateStr(s.to)}: ${s.items} sales across ${s.brands} brand(s)`,
    `Sales ${m(s.price)}, Poshmark fees ${m(s.fee)} (${(s.feeRate * 100).toFixed(1)}% effective), shipping deductions ${m(s.shippingLoss)}, payout ${m(s.payout)}`,
  ];
  if (s.costedItems) lines.push(`Cost ${m(s.cost)} on ${s.costedItems} item(s), profit ${m(s.profit)}${s.margin !== null ? ` (${(s.margin * 100).toFixed(0)}% of sale price)` : ""}, ${s.losingItems} losing`);
  else lines.push("No cost basis supplied: figures are payout before what the items cost");
  if (s.avgDays !== null) lines.push(`Days to sell: average ${s.avgDays.toFixed(0)}, median ${s.medianDays.toFixed(0)} (${s.daysItems} items)`);
  const top = r.byBrand.slice(0, 3).map((b) => `${b.label} ${m(b.profit ?? b.payout)}`);
  lines.push(`Top brands by ${r.rankBasis}: ${top.join("; ")}`);
  if (r.stopBrands.length) lines.push(`Consider not sourcing: ${r.stopBrands.map((b) => `${b.label} (${m(b.profit)})`).join("; ")}`);
  const w = r.worstItems[0], b = r.bestItems[0];
  if (w) lines.push(`Worst item: ${w.title || w.id || "(untitled)"} ${m(r.rankBasis === "profit" ? w.profit : w.payout)}; best: ${b.title || b.id || "(untitled)"} ${m(r.rankBasis === "profit" ? b.profit : b.payout)}`);
  lines.push("Made with the Poshmark Sales Report Analyzer (nothing uploaded). Estimates from the file supplied.");
  return lines.join("\n");
}

export const money = (n) => (Number.isFinite(n) ? (n < 0 ? "-" : "") + Math.abs(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : "–");
export const pct = (n) => (Number.isFinite(n) ? (n * 100).toFixed(0) + "%" : "–");
export const dateStr = (t) => new Date(t).toISOString().slice(0, 10);

// Synthetic, invented sales for the "Load an example" button. Not a real account.
export function sampleCsv() {
  const lines = ["Order ID,Order Date,Listed Date,Listing Title,Brand,SKU,Order Price,Poshmark Fee,Seller Shipping Discount,Net Earnings,Cost"];
  let seed = 7;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  const brands = [
    { name: "Lululemon", titles: ["Align leggings", "Define jacket", "Scuba hoodie"], price: [48, 78], cost: [14, 22], slow: 20 },
    { name: "Free People", titles: ["Boho dress", "Knit cardigan", "Lace top"], price: [32, 58], cost: [10, 18], slow: 35 },
    { name: "Zara", titles: ["Satin blouse", "Pleated skirt", "Crop tee"], price: [9, 14], cost: [6, 9], slow: 50 },
    { name: "Old Navy", titles: ["Tee", "Jogger", "Tank"], price: [7, 12], cost: [7, 11], slow: 70 },
    { name: "Nike", titles: ["Dri-FIT tee", "Tech fleece", "Running shorts"], price: [18, 36], cost: [8, 15], slow: 25 },
  ];
  let n = 0;
  for (let i = 0; i < 40; i++) {
    const b = brands[i % brands.length];
    const price = Math.round(b.price[0] + rnd() * (b.price[1] - b.price[0]));
    const cost = Math.round((b.cost[0] + rnd() * (b.cost[1] - b.cost[0])) * 100) / 100;
    const fee = r2(commissionFor(price).commission);
    const disc = rnd() < 0.2 ? 2 : 0;
    const sold = Date.UTC(2026, 3 + Math.floor(i / 14), 1 + ((i * 7) % 27));
    const listed = sold - Math.round(b.slow * (0.4 + rnd() * 1.2)) * DAY;
    n++;
    lines.push([`SAMPLE-${1000 + n}`, dateStr(sold), dateStr(listed), `${b.titles[i % 3]}`, b.name, `${b.name.slice(0, 3).toUpperCase()}-${String(n).padStart(3, "0")}`, price.toFixed(2), fee.toFixed(2), disc.toFixed(2), (price - fee - disc).toFixed(2), cost.toFixed(2)].join(","));
  }
  return lines.join("\n");
}

engines/shopify.mjs.text:
// Shopify shop analysis from two CSVs the merchant already has: the Shopify
// Payments "Transactions" export (every charge, fee, refund, dispute,
// adjustment and payout) and, optionally, the Orders export (which products
// each order held, the discount code used). Output is the fee waterfall,
// net-to-bank per order, effective fee rate by card and gateway, profit per
// product after unit costs, discount-code cost, dispute and refund findings
// and a monthly table. Pure functions, no DOM, no network.

const TX_ALIASES = {
  date: ["transaction date", "date"],
  type: ["type", "transaction type"],
  order: ["order", "order name", "order id"],
  cardBrand: ["card brand"],
  cardSource: ["card source"],
  payoutStatus: ["payout status"],
  payoutId: ["payout id"],
  amount: ["amount"],
  fee: ["fee", "fees"],
  net: ["net"],
  method: ["payment method name", "payment method"],
  presCurrency: ["presentment currency"],
  currency: ["currency"],
};

const ORDER_ALIASES = {
  name: ["name", "order", "order name"],
  financial: ["financial status"],
  paidAt: ["paid at", "created at"],
  subtotal: ["subtotal"],
  shipping: ["shipping"],
  taxes: ["taxes", "tax"],
  total: ["total"],
  code: ["discount code"],
  discount: ["discount amount"],
  qty: ["lineitem quantity"],
  item: ["lineitem name"],
  price: ["lineitem price"],
  sku: ["lineitem sku"],
  refunded: ["refunded amount"],
  method: ["payment method"],
};

export function parseCsv(text) {
  const rows = [];
  let row = [], field = "", quoted = false;
  const src = String(text ?? "").replace(/^﻿/, "");
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') { if (src[i + 1] === '"') { field += '"'; i++; } else quoted = false; }
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((f) => f.trim() !== "")) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((f) => f.trim() !== "")) rows.push(row);
  return rows;
}

const MONTHS = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };

// Shopify writes "2026-09-01 14:03:22 -0400"; older exports and spreadsheets
// re-saved by hand give "Sep 1, 2026" or "09/01/2026".
export function parseDate(value) {
  const s = String(value ?? "").trim();
  if (!s) return null;
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { y: +m[1], mo: +m[2] - 1, d: +m[3] };
  m = s.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})/);
  if (m && MONTHS[m[1].toLowerCase()] !== undefined) return { y: +m[3], mo: MONTHS[m[1].toLowerCase()], d: +m[2] };
  m = s.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})/);
  if (m && MONTHS[m[2].toLowerCase()] !== undefined) return { y: +m[3], mo: MONTHS[m[2].toLowerCase()], d: +m[1] };
  m = s.match(/^(\d{1,2})[/.](\d{1,2})[/.](\d{4})/);
  if (m) return { y: +m[3], mo: +m[1] - 1, d: +m[2] }; // US month-first
  return null;
}
const monthKeyOf = (p) => `${p.y}-${String(p.mo + 1).padStart(2, "0")}`;

// "" and "--" are zero, not errors; anything unparseable is NaN so the row is
// listed rather than counted as free.
export function parseMoney(value) {
  let s = String(value ?? "").trim();
  if (!s || /^-+$/.test(s)) return 0;
  let neg = false;
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
  if (/^\s*-/.test(s)) neg = true;
  s = s.replace(/[^0-9.,]/g, "");
  if (s.includes(",") && s.includes(".")) {
    s = s.lastIndexOf(",") > s.lastIndexOf(".") ? s.replace(/\./g, "").replace(",", ".") : s.replace(/,/g, "");
  } else if (s.includes(",")) {
    s = /,\d{1,2}$/.test(s) ? s.replace(",", ".") : s.replace(/,/g, "");
  }
  const n = parseFloat(s);
  if (Number.isNaN(n)) return NaN;
  return neg ? -n : n;
}

function findColumns(header, aliases) {
  const norm = header.map((h) => h.trim().toLowerCase());
  const cols = {};
  for (const [field, names] of Object.entries(aliases)) {
    for (const n of names) {
      const at = norm.indexOf(n);
      if (at !== -1) { cols[field] = at; break; }
    }
  }
  return cols;
}

function headerRowIndex(table, must) {
  for (let i = 0; i < Math.min(table.length, 20); i++) {
    const norm = table[i].map((h) => h.trim().toLowerCase());
    if (must.every((alts) => alts.some((a) => norm.includes(a)))) return i;
  }
  return -1;
}

// "#1001", "1001" and " #1001 " are the same order.
export const orderKey = (v) => String(v ?? "").trim().replace(/^#\s*/, "").toLowerCase();

// Transaction rows: one per money movement. `net` is signed from the shop's
// point of view. When the export has no Net column it is rebuilt as
// Amount - Fee (Shopify writes Fee as a positive cost).
export function normalizeTransactions(table) {
  if (!table.length) return { rows: [], skipped: [], error: "The transactions file is empty." };
  const h = headerRowIndex(table, [["type", "transaction type"], ["amount"], ["transaction date", "date"]]);
  if (h === -1) return { rows: [], skipped: [], error: "No header row found. Expected the Shopify Payments transactions export with columns like “Transaction Date”, “Type”, “Order”, “Amount”, “Fee” and “Net”." };
  const cols = findColumns(table[h], TX_ALIASES);
  const get = (r, f) => (cols[f] === undefined ? "" : (r[cols[f]] ?? "")).trim();
  const rows = [], skipped = [];
  for (let i = h + 1; i < table.length; i++) {
    const r = table[i];
    const line = i + 1;
    const date = parseDate(get(r, "date"));
    if (!date) { skipped.push({ line, reason: `unreadable date “${get(r, "date")}”` }); continue; }
    const amount = parseMoney(get(r, "amount"));
    const fee = parseMoney(get(r, "fee"));
    const hasNet = cols.net !== undefined && get(r, "net") !== "";
    const net = hasNet ? parseMoney(get(r, "net")) : amount - fee;
    if ([amount, fee, net].some(Number.isNaN)) { skipped.push({ line, reason: "unreadable amount, fee or net" }); continue; }
    const type = get(r, "type");
    rows.push({
      line, date, month: monthKeyOf(date),
      type, typeKey: type.toLowerCase().replace(/[\s-]+/g, "_"),
      order: get(r, "order"), orderKey: orderKey(get(r, "order")),
      cardBrand: get(r, "cardBrand").toLowerCase(), cardSource: get(r, "cardSource").toLowerCase(),
      payoutStatus: get(r, "payoutStatus").toLowerCase(), payoutId: get(r, "payoutId"),
      method: get(r, "method").toLowerCase(),
      currency: get(r, "currency").toUpperCase(), presCurrency: get(r, "presCurrency").toUpperCase(),
      amount, fee, net,
      // Net is trusted over the Fee column so the waterfall always reconciles.
      feeCost: amount - net,
      feeMismatch: hasNet && cols.fee !== undefined && Math.abs(amount - fee - net) > 0.011,
    });
  }
  return { rows, skipped, error: null };
}

// Orders export: one row per line item; extra lines of a multi-item order
// repeat only the order name, so order-level fields are taken from whichever
// row of the order carries them.
export function normalizeOrders(table) {
  if (!table.length) return { orders: [], skipped: [], error: null };
  const h = headerRowIndex(table, [["name", "order", "order name"], ["lineitem name"]]);
  if (h === -1) return { orders: [], skipped: [], error: "The orders file needs “Name” and “Lineitem name” columns. Export Shopify admin → Orders → Export → CSV for Excel, Numbers, or other spreadsheet programs." };
  const cols = findColumns(table[h], ORDER_ALIASES);
  const get = (r, f) => (cols[f] === undefined ? "" : (r[cols[f]] ?? "")).trim();
  const byKey = new Map(), skipped = [];
  for (let i = h + 1; i < table.length; i++) {
    const r = table[i];
    const line = i + 1;
    const name = get(r, "name");
    if (!name) { skipped.push({ line, reason: "no order name" }); continue; }
    const money = (f) => parseMoney(get(r, f));
    const qtyText = get(r, "qty"), priceText = get(r, "price");
    const price = money("price"), qty = qtyText === "" ? 1 : parseInt(qtyText, 10);
    const orderLevel = [money("subtotal"), money("taxes"), money("total"), money("discount"), money("refunded")];
    if (Number.isNaN(price) || Number.isNaN(qty) || orderLevel.some(Number.isNaN)) { skipped.push({ line, reason: "unreadable quantity, price or amount" }); continue; }
    const k = orderKey(name);
    if (!byKey.has(k)) byKey.set(k, { key: k, name, code: "", discount: 0, taxes: 0, total: 0, refunded: 0, paidAt: null, method: "", financial: "", items: [] });
    const o = byKey.get(k);
    if (get(r, "code") && !o.code) o.code = get(r, "code").toUpperCase();
    if (get(r, "discount") !== "" && !o.discount) o.discount = Math.abs(money("discount"));
    if (get(r, "taxes") !== "" && !o.taxes) o.taxes = money("taxes");
    if (get(r, "total") !== "" && !o.total) o.total = money("total");
    if (get(r, "refunded") !== "" && !o.refunded) o.refunded = Math.abs(money("refunded"));
    if (!o.paidAt) o.paidAt = parseDate(get(r, "paidAt"));
    if (!o.method) o.method = get(r, "method");
    if (!o.financial) o.financial = get(r, "financial");
    const item = get(r, "item");
    if (item) o.items.push({ line, name: item, sku: get(r, "sku"), quantity: qty || 1, price, gross: Math.max(0, price * (qty || 1)), priceText });
  }
  return { orders: [...byKey.values()], skipped, error: null };
}

const round2 = (n) => Math.round(n * 100) / 100;

// Every transaction row lands in exactly one category. Reversals are checked
// before refunds/disputes so "chargeback_won" is not read as a new dispute.
export function classify(r) {
  const y = r.typeKey;
  if (y === "payout") return "payout";
  if (/chargeback|dispute/.test(y)) return "dispute";
  if (/refund/.test(y)) return "refund";
  if (/third_?party|gateway|paypal|external/.test(y)) return "gateway";
  if (y === "charge" || y === "payment" || y === "capture" || y === "sale") return "charge";
  if (/adjust|reserve|correction|balance|payout_(failure|cancel|reversal)/.test(y)) return "adjustment";
  return "other";
}
const isDisputeReversal = (y) => /won|reversal|reversed|release/.test(y);

const BUCKETS = ["charges", "refunds", "disputes", "processing", "gateway", "disputeFees", "adjustments", "other"];

// One row becomes one or two signed parts that add up to its Net exactly.
function parts(cat, r) {
  const fee = -r.feeCost;
  switch (cat) {
    case "charge": return [["charges", r.amount], ["processing", fee]];
    case "refund": return [["refunds", r.amount], ["processing", fee]];
    case "dispute": return [["disputes", r.amount], ["disputeFees", fee]];
    case "gateway": return [["gateway", r.net]];
    case "adjustment": return [["adjustments", r.net]];
    default: return [["other", r.net]];
  }
}

const isPending = (s) => !!s && !/^(paid|complete|completed)$/.test(s);
const isCardBrand = (s) => !!s;

// costs: { [product name or SKU]: unit cost }
export function analyze(rows, orders = [], { costs = {}, returnsResellable = true, thirdPartyRate = 0 } = {}) {
  if (!rows.length) return { invalid: "No usable transaction rows." };
  const totals = Object.fromEntries(BUCKETS.map((b) => [b, 0]));
  const counts = {};
  let payouts = 0, pendingNet = 0, pendingRows = 0, feeMismatch = 0;
  const months = new Map(), txOrders = new Map(), cards = new Map(), gateways = new Map();
  const disputeStats = { opened: 0, won: 0, lostAmount: 0, recovered: 0 };
  const cur = { domestic: { n: 0, gross: 0, fee: 0 }, foreign: { n: 0, gross: 0, fee: 0 } };

  const month = (k) => {
    if (!months.has(k)) months.set(k, { key: k, charges: 0, fees: 0, refunds: 0, disputes: 0, other: 0, net: 0 });
    return months.get(k);
  };
  const txOrder = (r) => {
    if (!txOrders.has(r.orderKey)) txOrders.set(r.orderKey, { key: r.orderKey, id: r.order, month: r.month, charged: 0, processing: 0, gateway: 0, refunds: 0, disputes: 0, disputeFees: 0, other: 0, net: 0 });
    return txOrders.get(r.orderKey);
  };
  const group = (map, key) => {
    if (!map.has(key)) map.set(key, { key, count: 0, gross: 0, fee: 0 });
    return map.get(key);
  };

  for (const r of rows) {
    const cat = classify(r);
    counts[cat] = (counts[cat] || 0) + 1;
    if (r.feeMismatch) feeMismatch++;
    if (cat === "payout") { payouts += Math.abs(r.net); continue; }
    const m = month(r.month);
    m.net += r.net;
    const o = r.orderKey ? txOrder(r) : null;
    if (o) o.net += r.net;
    for (const [b, v] of parts(cat, r)) {
      totals[b] += v;
      if (b === "charges") m.charges += v;
      else if (b === "refunds") m.refunds += v;
      else if (b === "disputes") m.disputes += v;
      else if (b === "processing" || b === "gateway" || b === "disputeFees") m.fees += v;
      else m.other += v;
      if (o) o[b === "charges" ? "charged" : b] += v;
    }
    if (isPending(r.payoutStatus)) { pendingNet += r.net; pendingRows++; }
    if (cat === "dispute") {
      if (isDisputeReversal(r.typeKey)) { disputeStats.recovered += Math.max(0, r.amount); if (/won|reversal|reversed/.test(r.typeKey)) disputeStats.won++; }
      else if (/^(chargeback|dispute)$/.test(r.typeKey)) { disputeStats.opened++; disputeStats.lostAmount += Math.abs(Math.min(0, r.amount)); }
    }
    if (cat === "charge") {
      const card = group(cards, `${isCardBrand(r.cardBrand) ? r.cardBrand : "(no card brand)"} · ${r.cardSource || "source not stated"}`);
      const gw = group(gateways, r.method || "(not stated)");
      for (const g of [card, gw]) { g.count++; g.gross += r.amount; g.fee += r.feeCost; }
      const foreign = r.presCurrency && r.currency && r.presCurrency !== r.currency ? cur.foreign : cur.domestic;
      foreign.n++; foreign.gross += r.amount; foreign.fee += r.feeCost;
    }
  }

  const charges = totals.charges;
  const feeTotal = totals.processing + totals.gateway + totals.disputeFees;
  const operating = BUCKETS.reduce((a, b) => a + totals[b], 0);
  const rate = (g) => (g.gross ? g.fee / g.gross : 0);
  const rated = (map) => [...map.values()].map((g) => ({ ...g, rate: rate(g), avg: g.count ? g.gross / g.count : 0 })).sort((a, b) => b.gross - a.gross);

  // ---- per order, from transactions alone ----
  const orderList = [...txOrders.values()].filter((o) => o.charged !== 0 || o.refunds !== 0 || o.disputes !== 0).map((o) => ({
    ...o,
    fees: o.processing + o.gateway + o.disputeFees,
    netRate: o.charged > 0 ? o.net / o.charged : null,
    fullyRefunded: o.charged > 0 && -o.refunds >= o.charged * 0.95,
  })).sort((a, b) => a.key.localeCompare(b.key, undefined, { numeric: true }));
  const chargedOrders = orderList.filter((o) => o.charged > 0);

  // ---- per product, only where the orders file names the products ----
  const products = new Map();
  const product = (k, name, sku) => {
    if (!products.has(k)) products.set(k, { name, sku, units: 0, unitsRefunded: 0, orders: 0, gross: 0, discount: 0, revenue: 0, fees: 0, refunds: 0, net: 0 });
    return products.get(k);
  };
  let matchedOrders = 0, unmatchedOrders = 0, attributedNet = 0, otherGatewayOrders = 0, otherGatewayTotal = 0;
  const codes = new Map();
  let discountTotal = 0, grossLines = 0;
  for (const ord of orders) {
    const gross = ord.items.reduce((a, x) => a + x.gross, 0);
    const disc = Math.min(ord.discount, gross);
    grossLines += gross; discountTotal += disc;
    if (ord.method && !/shopify[ _]?payments|shop[ _]?pay|^shopify$/i.test(ord.method) && !/manual|cash|gift/i.test(ord.method)) { otherGatewayOrders++; otherGatewayTotal += ord.total; }
    const tx = txOrders.get(ord.key);
    const label = ord.code || (disc > 0 ? "(automatic discount)" : "");
    if (label) {
      if (!codes.has(label)) codes.set(label, { code: label, orders: 0, discount: 0, gross: 0, matched: 0, net: 0 });
      const c = codes.get(label);
      c.orders++; c.discount += disc; c.gross += gross;
      if (tx && tx.charged > 0) { c.matched++; c.net += tx.net; }
    }
    if (!ord.items.length) continue;
    if (!tx || tx.charged <= 0) { unmatchedOrders++; continue; }
    matchedOrders++;
    const refundFrac = Math.min(1, Math.max(0, -tx.refunds / tx.charged));
    const taxNet = ord.taxes > 0 ? ord.taxes * (1 - refundFrac) : 0;
    const attributable = tx.net - taxNet;
    const lineRev = ord.items.map((x) => (gross ? x.gross - disc * (x.gross / gross) : 0));
    const revTotal = lineRev.reduce((a, x) => a + x, 0);
    const fullyRefunded = -tx.refunds >= tx.charged * 0.95;
    ord.items.forEach((it, i) => {
      const share = revTotal > 0 ? lineRev[i] / revTotal : 1 / ord.items.length;
      const p = product(it.name.toLowerCase(), it.name, it.sku);
      p.units += it.quantity; p.orders++;
      p.gross += it.gross; p.discount += disc * (gross ? it.gross / gross : 0); p.revenue += lineRev[i];
      p.fees += (tx.processing + tx.gateway + tx.disputeFees) * share;
      p.refunds += (tx.refunds + tx.disputes) * share;
      p.net += attributable * share;
      if (fullyRefunded) p.unitsRefunded += it.quantity;
      attributedNet += attributable * share;
    });
  }
  const productList = [...products.values()].map((p) => {
    const cost = costs[p.name] ?? (p.sku ? costs[p.sku] : undefined);
    const hasCost = typeof cost === "number" && !Number.isNaN(cost);
    const netUnits = p.units - p.unitsRefunded;
    const costedUnits = returnsResellable ? Math.max(0, netUnits) : p.units;
    const cogs = hasCost ? cost * costedUnits : null;
    return {
      ...p, netUnits, unitCost: hasCost ? cost : null,
      refundRate: p.units ? p.unitsRefunded / p.units : 0,
      feeRate: p.revenue ? -p.fees / p.revenue : 0,
      cogs,
      profit: hasCost ? p.net - cogs : null,
      profitPerUnit: hasCost && netUnits > 0 ? (p.net - cogs) / netUnits : null,
      margin: hasCost && p.revenue ? (p.net - cogs) / p.revenue : null,
    };
  }).sort((a, b) => b.revenue - a.revenue);
  const codeList = [...codes.values()].map((c) => ({
    ...c, pct: c.gross ? c.discount / c.gross : 0, share: discountTotal ? c.discount / discountTotal : 0,
    netPerOrder: c.matched ? c.net / c.matched : null,
  })).sort((a, b) => b.discount - a.discount);

  const allCosted = productList.length > 0 && productList.every((p) => p.profit !== null);
  const anyCosted = productList.some((p) => p.profit !== null);
  const cogsTotal = productList.reduce((a, p) => a + (p.cogs ?? 0), 0);
  const monthList = [...months.values()].sort((a, b) => a.key.localeCompare(b.key));
  const tpRate = Number.isFinite(thirdPartyRate) && thirdPartyRate > 0 ? thirdPartyRate : 0;

  const summary = {
    firstMonth: monthList[0]?.key ?? "", lastMonth: monthList[monthList.length - 1]?.key ?? "",
    totals, charges, feeTotal, operating, payouts, counts, rowCount: rows.length,
    orderCount: chargedOrders.length,
    processingRate: charges ? -totals.processing / charges : 0,
    allFeeRate: charges ? -feeTotal / charges : 0,
    refundRate: charges ? -totals.refunds / charges : 0,
    disputeRate: chargedOrders.length ? disputeStats.opened / chargedOrders.length : 0,
    avgOrder: chargedOrders.length ? charges / chargedOrders.length : 0,
    avgNetPerOrder: chargedOrders.length ? chargedOrders.reduce((a, o) => a + o.net, 0) / chargedOrders.length : 0,
    disputes: disputeStats, pendingNet, pendingRows, feeMismatch,
    foreign: { ...cur.foreign, rate: rate(cur.foreign) }, domestic: { ...cur.domestic, rate: rate(cur.domestic) },
    matchedOrders, unmatchedOrders, productCount: productList.length,
    attributedNet, cogsTotal, allCosted, anyCosted,
    profit: anyCosted ? operating - cogsTotal : null,
    discountTotal, grossLines, discountRate: grossLines ? discountTotal / grossLines : 0,
    otherGatewayOrders, otherGatewayTotal,
    gatewayEstimate: tpRate ? otherGatewayTotal * tpRate : 0, thirdPartyRate: tpRate,
    ordersFileGiven: orders.length > 0,
  };
  const out = { summary, orders: orderList, products: productList, cards: rated(cards), gateways: rated(gateways), codes: codeList, months: monthList };
  out.findings = findings(summary, out);
  return out;
}

const $ = (n) => (n < 0 ? "-$" : "$") + Math.abs(Math.round(n)).toLocaleString("en-US");
const $2 = (n) => (n < 0 ? "-$" : "$") + Math.abs(n).toFixed(2);
const P = (x, d = 1) => (x * 100).toFixed(d) + "%";

function findings(s, a) {
  const out = [];
  const add = (severity, title, detail) => out.push({ severity, title, detail });
  const t = s.totals;

  if (s.charges > 0) {
    add("info", `Fees took ${P(s.allFeeRate)} of what customers paid`,
      `${$(-s.feeTotal)} of fees against ${$(s.charges)} of charges: processing ${$(-t.processing)} (${P(s.processingRate)}), third-party gateway ${$(-t.gateway)}, dispute fees ${$(-t.disputeFees)}. Compare the processing rate with the Shopify Payments rate on your plan and country; a rate well above it usually means international or manually keyed cards.`);
  }

  if (s.refundRate > 0.05) {
    const lostFees = a.orders.filter((o) => o.fullyRefunded).reduce((x, o) => x + o.processing, 0);
    add(s.refundRate > 0.1 ? "high" : "medium", `Refunds are ${P(s.refundRate)} of charges (${$(-t.refunds)})`,
      `Shopify does not normally return the processing fee on a refund, so each refund costs more than the sale it removes: about ${$(-lostFees)} of fees sit on orders that were refunded in full. Look at which products they were and fix the listing, sizing or delivery promise behind the top ones.`);
  }

  const d = s.disputes;
  if (d.opened > 0) {
    add(s.disputeRate > 0.01 || d.opened >= 3 ? "high" : "medium", `${d.opened} chargeback${d.opened > 1 ? "s" : ""}: ${$(d.lostAmount)} disputed, ${$(-t.disputeFees)} in dispute fees`,
      `That is ${P(s.disputeRate, 2)} of orders. ${d.won ? `${d.won} reversal${d.won > 1 ? "s" : ""} returned ${$(d.recovered)}.` : "None show a reversal in this file yet."} Fees are usually not returned even when a dispute is won, so a chargeback costs the fee on top of the sale. Card networks commonly watch shops whose dispute ratio approaches 1% of transactions; a clear billing descriptor, tracking on every order and prompt replies to evidence requests keep it down.`);
  }

  if (t.adjustments < 0 && -t.adjustments > s.charges * 0.005) {
    add("medium", `Adjustments took ${$(-t.adjustments)}`,
      `${s.counts.adjustment || 0} adjustment or reserve row(s) reduced the balance. Open the rows in the transactions export to see Shopify's reason; reserves usually come back later.`);
  }

  if (s.counts.other > 0) {
    add("info", `${s.counts.other} row${s.counts.other > 1 ? "s" : ""} of a type this tool does not recognise (${$(t.other)})`,
      "They are counted in the “Other rows” line so the waterfall still adds up to the bank total. If a type appears here regularly, tell us its name so it gets its own line.");
  }

  if (s.foreign.n >= 5 && s.domestic.n >= 5 && s.foreign.rate - s.domestic.rate > 0.005) {
    add("medium", `Charges presented in another currency cost ${P(s.foreign.rate)} vs ${P(s.domestic.rate)} at home`,
      `${s.foreign.n} charges were shown to the customer in a different currency than you are paid in, and their effective fee rate is ${P(s.foreign.rate - s.domestic.rate)} higher. If those orders are thin-margin, price them separately or check the international card surcharge on your plan.`);
  }

  const cardsBig = a.cards.filter((c) => c.count >= 5);
  if (cardsBig.length >= 2) {
    const hi = [...cardsBig].sort((x, y) => y.rate - x.rate)[0], lo = [...cardsBig].sort((x, y) => x.rate - y.rate)[0];
    if (hi.rate - lo.rate > 0.005) add("info", `Highest effective fee rate: ${hi.key} at ${P(hi.rate, 2)} (lowest ${lo.key} at ${P(lo.rate, 2)})`,
      "The gap is the fixed per-charge fee on small orders plus any card-type surcharge. Rates are fee divided by charge amount, so small baskets look worse.");
  }

  if (s.ordersFileGiven && s.discountRate > 0.08) {
    const top = a.codes[0];
    add(s.discountRate > 0.2 ? "high" : "medium", `Discounts cost ${P(s.discountRate)} of product sales (${$(s.discountTotal)})`,
      top ? `Biggest: ${top.code} at ${$(top.discount)} (${P(top.share, 0)} of all discount) across ${top.orders} orders. Check whether those orders would have come anyway, and whether the margin after the code still covers fees.` : "");
  }
  const codeOverlap = a.codes.find((c) => c.matched >= 5 && s.avgNetPerOrder > 0 && c.netPerOrder !== null && c.netPerOrder < s.avgNetPerOrder * 0.7);
  if (codeOverlap) {
    add("medium", `${codeOverlap.code} orders bring in ${$2(codeOverlap.netPerOrder)} to the bank vs ${$2(s.avgNetPerOrder)} on average`,
      "Net per order on that code is at least 30% below the shop average. That is before cost of goods, so the margin on those orders is thinner still.");
  }

  const losers = a.products.filter((x) => x.profit !== null && x.profit < 0 && x.units >= 2);
  if (losers.length) {
    const worst = [...losers].sort((x, y) => x.profit - y.profit).slice(0, 3);
    add("high", `${losers.length} product${losers.length > 1 ? "s" : ""} lose money after unit cost`,
      `Worst: ${worst.map((x) => `${x.name} (${$(x.profit)} on ${x.units} units)`).join("; ")}. Raise the price, cut the cost, or stop discounting and advertising it.`);
  }
  const thin = a.products.filter((x) => x.margin !== null && x.margin >= 0 && x.margin < 0.15 && x.units >= 5);
  if (thin.length) {
    add("medium", `${thin.length} product${thin.length > 1 ? "s" : ""} earn under 15% after unit cost`,
      `${thin.slice(0, 4).map((x) => `${x.name} ${P(x.margin)}`).join("; ")}. Shipping you pay and your time are not in the cost figure, so a thin margin here is thinner than it looks.`);
  }
  const refunded = a.products.filter((x) => x.units >= 5 && x.refundRate >= 0.1).sort((x, y) => y.refundRate - x.refundRate);
  if (refunded.length) {
    add("high", `${refunded.length} product${refunded.length > 1 ? "s" : ""} with 10%+ of units in fully refunded orders`,
      `${refunded.slice(0, 4).map((x) => `${x.name} ${P(x.refundRate)}`).join("; ")}.`);
  }

  if (a.months.length >= 4) {
    const r = (m) => (m.charges ? -m.fees / m.charges : null);
    const first = a.months.slice(0, 2).map(r).filter((x) => x !== null), last = a.months.slice(-2).map(r).filter((x) => x !== null);
    if (first.length && last.length) {
      const x = first.reduce((p, q) => p + q) / first.length, y = last.reduce((p, q) => p + q) / last.length;
      if (y - x > 0.01) add("medium", `Fees rose from ${P(x)} to ${P(y)} of charges`,
        `Comparing the first two and last two months. More disputes, more international cards or smaller baskets (the fixed fee weighs more on them) all push it up.`);
    }
  }

  if (s.otherGatewayOrders > 0) {
    add("medium", `${s.otherGatewayOrders} order${s.otherGatewayOrders > 1 ? "s were" : " was"} paid through another gateway (${$(s.otherGatewayTotal)})`,
      s.gatewayEstimate > 0
        ? `Those payments are not in a Shopify Payments transactions file, so their processor fees are missing here. Shopify also charges a third-party transaction fee unless you use Shopify Payments; at your ${P(s.thirdPartyRate)} that is about ${$(s.gatewayEstimate)}, shown as an estimate and not added to the waterfall.`
        : "Those payments are not in a Shopify Payments transactions file, so their processor fees are missing here. Shopify also charges a third-party transaction fee unless you use Shopify Payments; enter its rate for your plan to see an estimate.");
  }

  if (s.pendingRows > 0 && Math.abs(s.pendingNet) >= 1) {
    add("info", `${$(s.pendingNet)} has not been paid out yet`,
      `${s.pendingRows} row${s.pendingRows > 1 ? "s" : ""} have a payout status other than paid. The bank total in the waterfall includes them, so your deposits will lag it by this amount.`);
  }
  if (s.feeMismatch > 0) {
    add("info", `${s.feeMismatch} row${s.feeMismatch > 1 ? "s" : ""} where Net is not Amount minus Fee`,
      "The Net column was used, so totals match what reached the balance. Check those rows if you compare against your own records.");
  }

  if (!s.ordersFileGiven) {
    add("info", "Add the Orders export to see profit per product and discount cost",
      "The transactions file names orders, not products. Export Orders from Shopify admin and add it above to split each order's net across its line items and to see the cost of discount codes.");
  } else if (s.unmatchedOrders > 0) {
    add("info", `${s.unmatchedOrders} order${s.unmatchedOrders > 1 ? "s" : ""} in the orders file have no charge in the transactions file`,
      "Their payments fall outside the transactions date range, went through another gateway, or were free. They are left out of per-product figures rather than counted as free.");
  }
  if (s.productCount > 0 && !s.anyCosted) {
    add("info", "Enter your unit costs to see real profit",
      "Product cost, shipping you pay and packaging are not in either Shopify file. Type a cost per unit next to each product (or paste name,cost lines) and profit, margin and loss-maker findings appear.");
  } else if (s.productCount > 0 && !s.allCosted) {
    add("info", "Some products have no unit cost yet", "Profit for those products is left out rather than counted as free.");
  }

  const order = { high: 0, medium: 1, info: 2 };
  return out.sort((x, y) => order[x.severity] - order[y.severity]);
}

export function parseCosts(text) {
  const costs = {};
  const bad = [];
  String(text ?? "").split(/\r?\n/).forEach((line, i) => {
    if (!line.trim()) return;
    const cells = parseCsv(line)[0] || [];
    if (cells.length < 2) { bad.push(i + 1); return; }
    const v = parseMoney(cells[cells.length - 1]);
    const k = cells.slice(0, -1).join(",").trim();
    if (!k || Number.isNaN(v) || v < 0) { if (i > 0 || !/^(name|product|item|sku)/i.test(k)) bad.push(i + 1); return; }
    costs[k] = v;
  });
  return { costs, bad };
}

const PRODUCTS = [
  { name: "Merino Beanie - Charcoal", price: 32, per: 22, cost: 9.5, refund: 0.03, sku: "BEAN-CH" },
  { name: "Ceramic Pour-over Set", price: 68, per: 10, cost: 27, refund: 0.07, sku: "POUR-01" },
  { name: "Cold Brew Concentrate 1L", price: 18, per: 26, cost: 8.4, refund: 0.1, sku: "CB-1L" },
  { name: "Canvas Weekender Bag", price: 96, per: 6, cost: 41, refund: 0.05, sku: "BAG-WK" },
];
const CODES = [["", 0], ["WELCOME10", 0.1], ["SPRING25", 0.25], ["", 0]];
const CARDS = [["visa", "online"], ["master", "online"], ["american_express", "online"], ["visa", "pos"], ["discover", "online"]];

// Deterministic synthetic shop: returns { transactions, orders, costs } as text.
export function sampleData() {
  const txHead = "Transaction Date,Type,Order,Card Brand,Card Source,Payout Status,Payout Date,Payout ID,Available On,Amount,Fee,Net,Checkout,Payment Method Name,Presentment Amount,Presentment Currency,Currency,Vat";
  const orHead = "Name,Email,Financial Status,Paid at,Fulfillment Status,Currency,Subtotal,Shipping,Taxes,Total,Discount Code,Discount Amount,Payment Method,Refunded Amount,Lineitem quantity,Lineitem name,Lineitem price,Lineitem sku";
  const tx = [txHead], or = [orHead];
  const q = (s) => `"${String(s).replace(/"/g, '""')}"`;
  const f = (n) => round2(n).toFixed(2);
  const names = ["06", "07", "08", "09"];
  let n = 0, payoutId = 7000;
  const txRow = (date, type, order, brand, source, status, amount, fee, method, pres, cur) =>
    tx.push([`${date} 12:${String(10 + (n % 40))}:05 -0400`, type, order, brand, source, status, "", status === "paid" ? payoutId : "", date, f(amount), f(fee), f(amount - fee), "", method, f(pres ?? amount), cur === "USD" ? "USD" : cur, "USD", ""].join(","));
  names.forEach((mm, mi) => {
    const status = mi === 3 ? "pending" : "paid";
    PRODUCTS.forEach((p, pi) => {
      const count = Math.round(p.per * (1 + mi * 0.1));
      for (let i = 0; i < count; i++) {
        n++;
        const day = String(1 + ((i * 3 + pi + mi) % 27)).padStart(2, "0");
        const date = `2026-${mm}-${day}`;
        const name = `#${1000 + n}`;
        const [code, pct] = CODES[(i + pi) % 4];
        const qty = i % 7 === 3 ? 2 : 1;
        const bag = pi === 0 && i % 5 === 0; // some orders also hold a second product
        const lines = [[p, qty]];
        if (bag) lines.push([PRODUCTS[2], 1]);
        const gross = lines.reduce((a, [x, k]) => a + x.price * k, 0);
        const disc = round2(gross * pct);
        const ship = gross > 60 ? 0 : 6.5, tax = round2((gross - disc) * 0.07);
        const total = round2(gross - disc + ship + tax);
        const [brand, source] = CARDS[(i + mi) % 5];
        const foreign = i % 9 === 4;
        const fee = round2(total * (foreign ? 0.049 : source === "pos" ? 0.026 : 0.029) + (source === "pos" ? 0.1 : 0.3));
        const paypal = i % 13 === 6;
        const method = paypal ? "PayPal Express Checkout" : "Shopify Payments";
        const refunded = !paypal && i > 0 && (i + mi * 2) % Math.round(1 / p.refund) === 0;
        lines.forEach(([x, k], li) => {
          const first = li === 0;
          or.push([name, "shopper@example.com", "paid", first ? `${date} 12:00:00 -0400` : "", "fulfilled", "USD", first ? f(gross) : "", first ? f(ship) : "", first ? f(tax) : "", first ? f(total) : "", first ? code : "", first ? f(disc) : "", first ? method : "", first && refunded ? f(total) : "", k, q(x.name), f(x.price), x.sku].join(","));
        });
        if (!paypal) {
          txRow(date, "charge", name, brand, source, status, total, fee, brand, foreign ? total * 1.35 : total, foreign ? "CAD" : "USD");
          if (refunded) {
            txRow(date, "refund", name, brand, source, status, -total, 0, brand, -total, "USD");
          } else if (i > 0 && i % 23 === 0) {
            txRow(date, "chargeback", name, brand, source, status, -total, 15, brand, -total, "USD");
            if (mi === 1) txRow(date, "chargeback_won", name, brand, source, status, total, -15, brand, total, "USD");
          }
        }
      }
    });
    tx.push([`2026-${mm}-14 03:00:00 -0400`, "adjustment", "", "", "", status, "", "", `2026-${mm}-14`, mi === 2 ? "-42.00" : "-3.50", "0.00", mi === 2 ? "-42.00" : "-3.50", "", "", "", "USD", "USD", ""].join(","));
    tx.push([`2026-${mm}-15 03:00:00 -0400`, "shopify_capital_repayment", "", "", "", status, "", "", `2026-${mm}-15`, "-25.00", "0.00", "-25.00", "", "", "", "USD", "USD", ""].join(","));
    payoutId++;
    tx.push([`2026-${mm}-28 03:00:00 -0400`, "payout", "", "", "", status, `2026-${mm}-28`, payoutId, `2026-${mm}-28`, "800.00", "0.00", "800.00", "", "", "", "USD", "USD", ""].join(","));
  });
  const costs = PRODUCTS.map((p) => `${p.name},${p.cost.toFixed(2)}`);
  return { transactions: tx.join("\n"), orders: or.join("\n"), costs: "name,cost\n" + costs.join("\n") };
}

export const money = $;
export const money2 = $2;
export const pct = P;

engines/whatnot.mjs.text:
// Per-sale, per-show and per-category profit analysis from a Whatnot seller
// orders/sales CSV. Column names are matched by alias from memory of Whatnot's
// seller export; no real export was available when this was written. Pure
// functions, no DOM, no network.
//
// Fee model (same published shape as ../whatnot-seller-payout/calc.mjs, a test
// asserts the constants stay equal): commission is a percentage of the item
// price; payment processing is a percentage of what the buyer paid (item +
// shipping + tax) plus a flat 30 cents. Both rates are editable inputs, not a
// live lookup.

export const DEFAULT_COMMISSION_RATE = 8;
export const DEFAULT_PAYMENT_RATE = 2.9;
export const DEFAULT_PAYMENT_FIXED = 0.3;

export function scheduleFee(price, buyerShipping = 0, tax = 0, { commissionRate = DEFAULT_COMMISSION_RATE, paymentRate = DEFAULT_PAYMENT_RATE, paymentFixed = DEFAULT_PAYMENT_FIXED } = {}) {
  const commission = price * (commissionRate / 100);
  const processing = (price + buyerShipping + tax) * (paymentRate / 100) + paymentFixed;
  return { commission, processing, fee: commission + processing };
}

const ALIASES = {
  id: ["order id", "order #", "order number", "order no", "order", "id", "sale id", "transaction id"],
  date: ["order date", "sale date", "date sold", "sold date", "date of sale", "sold on", "order placed", "date", "order date/time", "sold at", "created at", "created"],
  title: ["product name", "item name", "item title", "title", "listing title", "item", "product", "description", "listing", "name"],
  show: ["show", "show name", "stream", "stream title", "livestream", "live stream", "show title", "show id"],
  category: ["category", "product category", "item category", "sub category", "subcategory"],
  sku: ["sku", "custom sku", "item sku", "seller sku", "custom label"],
  price: ["sold price", "sale price", "item price", "price", "hammer", "hammer price", "item subtotal", "subtotal", "gross", "sales", "amount sold", "sold for"],
  buyerShip: ["shipping charged", "buyer shipping", "shipping paid by buyer", "shipping fee", "shipping price", "shipping"],
  tax: ["sales tax", "tax", "tax collected", "buyer tax"],
  commission: ["commission", "commission fee", "whatnot commission", "selling fee", "seller fee", "marketplace fee"],
  processing: ["processing fee", "payment processing fee", "payment processing", "processing", "payment fee"],
  fee: ["total fees", "fees", "fee", "whatnot fee", "whatnot fees", "total fee"],
  net: ["net earnings", "earnings", "net payout", "payout", "seller payout", "net proceeds", "proceeds", "net", "your earnings", "seller earnings"],
  cost: ["cost", "item cost", "cost basis", "purchase price", "cogs", "my cost", "cost of goods", "cost of goods sold", "sourcing cost", "cost price", "buy price", "paid"],
  status: ["order status", "status", "state", "sale status"],
  currency: ["currency"],
};

export function parseNumber(v, decimalComma = false) {
  let s = String(v ?? "").trim();
  if (s === "" || /^[-–—\s]+$/.test(s)) return 0;
  const neg = /^\(.*\)$/.test(s) || /^[-−]/.test(s);
  s = s.replace(/[^0-9.,]/g, "");
  s = decimalComma ? s.replace(/\./g, "").replace(",", ".") : s.replace(/,/g, "");
  const n = Number(s);
  if (!s || !Number.isFinite(n)) return NaN;
  return neg ? -n : n;
}

export function decodeBuffer(buf) {
  const u8 = new Uint8Array(buf);
  if (u8[0] === 0xff && u8[1] === 0xfe) return new TextDecoder("utf-16le").decode(u8);
  if (u8[0] === 0xfe && u8[1] === 0xff) return new TextDecoder("utf-16be").decode(u8);
  return new TextDecoder("utf-8").decode(u8);
}

export function detectDelimiter(text) {
  const head = String(text ?? "").split(/\r?\n/).filter((l) => l.trim()).slice(0, 8).join("\n");
  const n = (c) => head.split(c).length - 1;
  const best = [["\t", n("\t")], [";", n(";")], [",", n(",")]].sort((a, b) => b[1] - a[1])[0];
  return best[1] > 0 ? best[0] : ",";
}

export function parseCsv(text, delim = ",") {
  const rows = [];
  let row = [], field = "", quoted = false;
  const src = String(text ?? "").replace(/^﻿/, "");
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') { if (src[i + 1] === '"') { field += '"'; i++; } else quoted = false; }
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === delim) { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((f) => f.trim() !== "")) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((f) => f.trim() !== "")) rows.push(row);
  return rows;
}

export function parseWhen(v, dmy = false) {
  const s = String(v ?? "").trim();
  if (!s) return null;
  let y, mo, d, rest = "";
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(.*)$/);
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; rest = m[4]; }
  else {
    m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2,4})(.*)$/);
    if (!m) return null;
    const a = +m[1], b = +m[2];
    y = +m[3]; if (y < 100) y += 2000;
    if (dmy) { d = a; mo = b; } else { mo = a; d = b; }
    rest = m[4];
  }
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  let hh = 0, mm = 0, hasTime = false;
  const tm = rest.match(/(\d{1,2}):(\d{2})(?::\d{2})?\s*([ap]\.?m\.?)?/i);
  if (tm) {
    hh = +tm[1]; mm = +tm[2]; hasTime = true;
    const ap = tm[3] ? tm[3][0].toLowerCase() : "";
    if (ap === "p" && hh < 12) hh += 12;
    if (ap === "a" && hh === 12) hh = 0;
    if (hh > 23 || mm > 59) return null;
  }
  const t = Date.UTC(y, mo - 1, d, hh, mm);
  return new Date(t).getUTCDate() === d ? { t, hasTime } : null;
}

export function detectDmy(values) {
  let first = false, second = false;
  for (const v of values) {
    const m = String(v ?? "").trim().match(/^(\d{1,2})[/.-](\d{1,2})[/.-]\d{2,4}/);
    if (!m) continue;
    if (+m[1] > 12) first = true;
    if (+m[2] > 12) second = true;
  }
  return first && !second;
}
function findColumns(header) {
  const norm = header.map((h) => h.trim().toLowerCase());
  const cols = {};
  for (const [field, names] of Object.entries(ALIASES)) {
    for (const n of names) {
      const at = norm.indexOf(n);
      if (at !== -1 && !Object.values(cols).includes(at)) { cols[field] = at; break; }
    }
  }
  return cols;
}

const DAY = 86400000;
export const MIN_GROUP_ITEMS = 3;
export const FEE_MODES = ["auto", "schedule"];
const r2 = (n) => Math.round(n * 100) / 100;
const isBlank = (s) => s === "" || /^[-–—\s]+$/.test(s);
const norm = (s) => String(s ?? "").toLowerCase().replace(/\s+/g, " ").trim();
const usd = (n) => (n < 0 ? "-" : "") + "$" + Math.abs(n).toFixed(2);

// Returns { items, skipped, excludedCount, currency, columns, dmy, feeSource, error }.
// An item is { line, id, title, show, category, sku, t, price, fee, scheduleFee,
// payout, deductions, cost } where cost is null when the file does not say.
// feeMode "auto" reads the file's fee columns when there are any and otherwise
// applies the rates; "schedule" always applies the rates. Cancelled, returned
// and refunded orders are left out and counted.
export function normalizeRows(table, { decimalComma = false, feeMode = "auto", commissionRate = DEFAULT_COMMISSION_RATE, paymentRate = DEFAULT_PAYMENT_RATE, paymentFixed = DEFAULT_PAYMENT_FIXED } = {}) {
  const empty = { items: [], skipped: [], excludedCount: 0, currency: "", columns: {}, dmy: false, feeSource: "schedule" };
  if (!table.length) return { ...empty, error: "The file is empty." };
  let h = -1;
  for (let i = 0; i < Math.min(table.length, 10); i++) {
    const c = findColumns(table[i]);
    if (c.date !== undefined && c.price !== undefined) { h = i; break; }
  }
  if (h < 0) return { ...empty, error: "No header row found. Expected columns like “Order Date” and “Sold Price” (or “Sale Price”), plus ideally “Product Name”, “Show”, “Category”, “Commission”, “Processing Fee”, “Net Earnings” and a cost column. Download your orders from Whatnot Seller Hub or make a sheet with those headers." };
  const cols = findColumns(table[h]);
  const get = (line, f) => (cols[f] === undefined ? "" : (line[cols[f]] ?? "").trim());
  const dmy = detectDmy(table.slice(h + 1).map((l) => get(l, "date")));
  const hasFeeCols = cols.fee !== undefined || cols.commission !== undefined || cols.processing !== undefined;
  const feeSource = feeMode !== "schedule" && hasFeeCols ? "column" : "schedule";
  const rates = { commissionRate, paymentRate, paymentFixed };

  const items = [], skipped = [];
  let currency = "", excludedCount = 0;
  for (let i = h + 1; i < table.length; i++) {
    const line = table[i];
    const lineNo = i + 1;
    if (line.every((x) => !String(x).trim())) continue;
    const first = String(line[0] ?? "").trim().toLowerCase();
    if (/^(total|totals|subtotal|grand total|summary)\b/.test(first)) { skipped.push({ line: lineNo, reason: "total row" }); continue; }
    const when = parseWhen(get(line, "date"), dmy);
    if (!when) { skipped.push({ line: lineNo, reason: "date not readable" }); continue; }
    const price = parseNumber(get(line, "price"), decimalComma);
    if (!Number.isFinite(price)) { skipped.push({ line: lineNo, reason: "price not readable" }); continue; }
    if (!(price > 0)) { skipped.push({ line: lineNo, reason: "no sale price" }); continue; }
    if (/cancel|return|refund|declin|fail/i.test(get(line, "status"))) { excludedCount++; continue; }
    const money = (f) => {
      const raw = get(line, f);
      if (cols[f] === undefined || isBlank(raw)) return null;
      const v = parseNumber(raw, decimalComma);
      return Number.isFinite(v) ? v : null;
    };
    const sched = r2(scheduleFee(price, Math.abs(money("buyerShip") ?? 0), Math.abs(money("tax") ?? 0), rates).fee);
    let fee = sched;
    if (feeSource === "column") {
      const total = money("fee"), c = money("commission"), p = money("processing");
      if (c !== null || p !== null) fee = r2(Math.abs(c ?? 0) + Math.abs(p ?? 0));
      else if (total !== null) fee = r2(Math.abs(total));
    }
    const netFile = money("net");
    const expected = price - fee;
    let payout, deductions;
    if (netFile !== null) {
      // The file's own net is trusted. Anything it takes off beyond the fees is
      // an unexplained deduction (a shipping label the seller paid, a chargeback).
      payout = netFile;
      const gap = expected - netFile;
      deductions = gap > 0.005 ? gap : 0;
    } else {
      payout = expected;
      deductions = 0;
    }
    const cur = get(line, "currency");
    if (cur && !currency) currency = cur;
    const cost = money("cost");
    items.push({
      line: lineNo, id: get(line, "id"), title: get(line, "title"), show: get(line, "show"), category: get(line, "category"), sku: get(line, "sku"),
      t: when.t, price: r2(price), fee, scheduleFee: sched, payout: r2(payout), deductions: r2(deductions), cost: cost === null ? null : r2(cost),
    });
  }
  if (!items.length) return { ...empty, skipped, excludedCount, currency, columns: cols, dmy, feeSource, error: "No sales could be read from the file. " + (skipped.length ? `${skipped.length} row(s) were skipped (first: line ${skipped[0].line}, ${skipped[0].reason}).` : "Every order was cancelled, returned or refunded.") };
  return { items, skipped, excludedCount, currency, columns: cols, dmy, feeSource };
}

// Pasted cost basis: one "SKU, cost" pair per line (comma, tab or semicolon; the
// last separator splits, so a title with commas still works). A first line whose
// cost is not a number is treated as a header. Returns { map, count, errors }.
export function parseCostList(text) {
  const map = new Map(), errors = [];
  const lines = String(text ?? "").split(/\r?\n/);
  let count = 0;
  lines.forEach((raw, idx) => {
    const line = raw.trim();
    if (!line) return;
    const at = Math.max(line.lastIndexOf(","), line.lastIndexOf("\t"), line.lastIndexOf(";"));
    if (at <= 0) { errors.push({ line: idx + 1, reason: "needs a name, a separator and a cost" }); return; }
    const key = norm(line.slice(0, at).replace(/^"|"$/g, ""));
    const cost = parseNumber(line.slice(at + 1).replace(/^"|"$/g, ""));
    if (!key || !Number.isFinite(cost) || line.slice(at + 1).trim() === "") {
      if (idx === 0) return;
      errors.push({ line: idx + 1, reason: "cost is not a number" });
      return;
    }
    if (cost < 0) { errors.push({ line: idx + 1, reason: "cost is negative" }); return; }
    map.set(key, cost);
    count++;
  });
  return { map, count, errors };
}

function rollup(label, list) {
  const price = list.reduce((s, x) => s + x.price, 0);
  const fee = list.reduce((s, x) => s + x.fee, 0);
  const payout = list.reduce((s, x) => s + x.payout, 0);
  const costed = list.filter((x) => x.cost !== null);
  const costedPrice = costed.reduce((s, x) => s + x.price, 0);
  const cost = costed.reduce((s, x) => s + x.cost, 0);
  const profit = costed.reduce((s, x) => s + x.profit, 0);
  return {
    label, items: list.length, price: r2(price), fee: r2(fee), feeRate: price > 0 ? fee / price : null,
    deductions: r2(list.reduce((s, x) => s + x.deductions, 0)), payout: r2(payout),
    costedItems: costed.length, cost: r2(cost), profit: costed.length ? r2(profit) : null,
    margin: costed.length && costedPrice > 0 ? profit / costedPrice : null,
    avgPrice: list.length ? price / list.length : null,
  };
}

const monthKey = (t) => new Date(t).toISOString().slice(0, 7);

// items: normalizeRows(...).items. costList: pasted text (overrides the file's
// cost column for any item it matches, by SKU, then order id, then title).
export function analyze(rawItems, { costList = "", from = null, to = null, minGroupItems = MIN_GROUP_ITEMS, lowPrice = 10 } = {}) {
  const parsedList = parseCostList(costList);
  const matchedKeys = new Set();
  let items = rawItems.filter((x) => (from === null || x.t >= from) && (to === null || x.t < to + DAY));
  if (!items.length) return { invalid: "No sales fall inside the date range you chose." };
  items = items.map((x) => {
    let cost = x.cost, costSource = x.cost === null ? null : "file";
    for (const k of [norm(x.sku), norm(x.id), norm(x.title)]) {
      if (k && parsedList.map.has(k)) { cost = r2(parsedList.map.get(k)); costSource = "list"; matchedKeys.add(k); break; }
    }
    const profit = cost === null ? null : r2(x.payout - cost);
    return { ...x, cost, costSource, profit, showLabel: x.show || "(no show)", categoryLabel: x.category || "(no category)", effectiveFeeRate: x.price > 0 ? x.fee / x.price : null };
  });
  const unmatched = [...parsedList.map.keys()].filter((k) => !matchedKeys.has(k));

  const group = (keyFn, sortFn) => {
    const m = new Map();
    for (const x of items) { const k = keyFn(x); (m.get(k) ?? m.set(k, []).get(k)).push(x); }
    return [...m].map(([k, list]) => rollup(k, list)).sort(sortFn);
  };
  const byValue = (a, b) => ((b.profit ?? b.payout) - (a.profit ?? a.payout)) || (b.items - a.items);
  const byMonth = group((x) => monthKey(x.t), (a, b) => (a.label < b.label ? -1 : 1));
  const byShow = group((x) => x.showLabel, byValue);
  const byCategory = group((x) => x.categoryLabel, byValue);

  const total = rollup("All", items);
  const costed = items.filter((x) => x.cost !== null);
  const rankBasis = costed.length ? "profit" : "payout";
  const rankPool = costed.length ? costed : items;
  const metric = (x) => (rankBasis === "profit" ? x.profit : x.payout);
  const worstItems = [...rankPool].sort((a, b) => metric(a) - metric(b)).slice(0, 10);
  const bestItems = [...rankPool].sort((a, b) => metric(b) - metric(a)).slice(0, 10);
  const losing = costed.filter((x) => x.profit < 0);

  const cheap = items.filter((x) => x.price < lowPrice);
  const cheapFees = cheap.reduce((s, x) => s + x.fee, 0), cheapSales = cheap.reduce((s, x) => s + x.price, 0);
  const feeMismatch = items.filter((x) => Math.abs(x.fee - x.scheduleFee) > 0.05);
  const deducted = items.filter((x) => x.deductions > 0.005);

  const losers = (groups) => groups.filter((g) => g.costedItems >= minGroupItems && g.profit < 0 && !g.label.startsWith("("));
  const stopShows = losers(byShow), stopCategories = losers(byCategory);
  const thinCategories = byCategory.filter((g) => g.costedItems >= minGroupItems && g.profit >= 0 && g.margin !== null && g.margin < 0.1 && !g.label.startsWith("("));
  const feeHeavy = costed.length ? [] : byCategory.filter((g) => g.items >= minGroupItems && g.feeRate >= 0.15 && !g.label.startsWith("("));

  const findings = [];
  if (!costed.length) findings.push({ severity: "high", title: "No cost basis, so nothing here is profit yet", detail: "Payout below is sale price minus Whatnot's fees (and any other deduction in the file), before what you paid for the item. Add a cost column to the file or paste SKU,cost pairs in step 2 to see profit, losing sales, and the shows and categories that lose money." });
  else if (costed.length < items.length) findings.push({ severity: "medium", title: `${items.length - costed.length} of ${items.length} sales have no cost`, detail: `Profit, margin and the show and category verdicts use only the ${costed.length} sales with a cost. Payout totals cover all ${items.length}.` });
  if (losing.length) findings.push({ severity: "high", title: `${losing.length} sale${losing.length === 1 ? "" : "s"} lost money after fees and cost`, detail: `Together ${usd(losing.reduce((s, x) => s + x.profit, 0))}. The worst are listed below.` });
  if (stopCategories.length) findings.push({ severity: "high", title: `Categories that lost money: ${stopCategories.map((g) => g.label).join(", ")}`, detail: stopCategories.map((g) => `${g.label}: ${usd(g.profit)} over ${g.costedItems} costed sales (${(g.feeRate * 100).toFixed(0)}% effective fee)`).join("; ") + `. A group needs at least ${minGroupItems} costed sales to be named.` });
  if (stopShows.length) findings.push({ severity: "high", title: `Shows that lost money: ${stopShows.map((g) => g.label).join(", ")}`, detail: stopShows.map((g) => `${g.label}: ${usd(g.profit)} over ${g.costedItems} costed sales`).join("; ") + ". Look at your starting bids, and whether the lots sold below what they cost." });
  if (thinCategories.length) findings.push({ severity: "medium", title: `Thin margin categories: ${thinCategories.map((g) => g.label).join(", ")}`, detail: thinCategories.map((g) => `${g.label}: ${(g.margin * 100).toFixed(0)}% of sale price kept as profit`).join("; ") + "." });
  if (feeHeavy.length) findings.push({ severity: "medium", title: `Fees take 15% or more of the price: ${feeHeavy.map((g) => g.label).join(", ")}`, detail: "The flat 30 cents and the processing on shipping and tax weigh on small sales. Without a cost column this is the only sourcing signal the file can give." });
  if (cheap.length) findings.push({ severity: cheapSales > 0 && cheapFees / cheapSales >= 0.15 ? "medium" : "info", title: `${cheap.length} sale${cheap.length === 1 ? "" : "s"} under ${usd(lowPrice)} paid ${(cheapFees / cheapSales * 100).toFixed(0)}% in fees`, detail: `${usd(cheapFees)} in fees on ${usd(cheapSales)} of sales. The flat 30 cents of processing is a fixed cost per order, so the smaller the sale, the bigger its share.` });
  if (deducted.length) findings.push({ severity: "medium", title: `${deducted.length} sale${deducted.length === 1 ? "" : "s"} paid out less than price minus fees`, detail: `${usd(deducted.reduce((s, x) => s + x.deductions, 0))} in total, an average of ${usd(deducted.reduce((s, x) => s + x.deductions, 0) / deducted.length)} on those sales. The file's net figure is used as your payout; the gap can be a shipping label, an adjustment or a fee column the file does not itemise.` });
  if (feeMismatch.length) findings.push({ severity: "info", title: `${feeMismatch.length} fee${feeMismatch.length === 1 ? "" : "s"} in the file differ from the rates used here`, detail: "The fee in your file is used. Category rates, promotions, a different processor rate or an old schedule can explain this; check a few against your own statement." });

  return {
    items, byShow, byCategory, byMonth, worstItems, bestItems, rankBasis, findings, stopShows, stopCategories, thinCategories, unmatched, costList: { count: parsedList.count, errors: parsedList.errors },
    summary: {
      ...total, from: Math.min(...items.map((x) => x.t)), to: Math.max(...items.map((x) => x.t)), shows: byShow.filter((g) => !g.label.startsWith("(")).length, categories: byCategory.filter((g) => !g.label.startsWith("(")).length,
      losingItems: losing.length, cheapItems: cheap.length, deductionItems: deducted.length, feeMismatches: feeMismatch.length,
    },
  };
}

export const money = (n) => (Number.isFinite(n) ? (n < 0 ? "-" : "") + Math.abs(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : "–");
export const pct = (n) => (Number.isFinite(n) ? (n * 100).toFixed(0) + "%" : "–");
export const dateStr = (t) => new Date(t).toISOString().slice(0, 10);

// Plain text for pasting into a note, a forum post or a message to yourself.
export function summaryText(r, { currency = "" } = {}) {
  const s = r.summary, c = currency ? currency + " " : "";
  const m = (n) => (Number.isFinite(n) ? (n < 0 ? "-" : "") + c + "$" + Math.abs(n).toFixed(2) : "n/a");
  const lines = [
    `Whatnot sales ${dateStr(s.from)} to ${dateStr(s.to)}: ${s.items} sales, ${s.shows} show(s), ${s.categories} categor${s.categories === 1 ? "y" : "ies"}`,
    `Sales ${m(s.price)}, Whatnot fees ${m(s.fee)} (${(s.feeRate * 100).toFixed(1)}% effective), other deductions ${m(s.deductions)}, payout ${m(s.payout)}`,
  ];
  if (s.costedItems) lines.push(`Cost ${m(s.cost)} on ${s.costedItems} item(s), profit ${m(s.profit)}${s.margin !== null ? ` (${(s.margin * 100).toFixed(0)}% of sale price)` : ""}, ${s.losingItems} losing`);
  else lines.push("No cost basis supplied: figures are payout before what the items cost");
  const top = r.byCategory.slice(0, 3).map((g) => `${g.label} ${m(g.profit ?? g.payout)}`);
  lines.push(`Top categories by ${r.rankBasis}: ${top.join("; ")}`);
  if (r.stopCategories.length) lines.push(`Categories that lost money: ${r.stopCategories.map((g) => `${g.label} (${m(g.profit)})`).join("; ")}`);
  if (r.stopShows.length) lines.push(`Shows that lost money: ${r.stopShows.map((g) => `${g.label} (${m(g.profit)})`).join("; ")}`);
  const w = r.worstItems[0], b = r.bestItems[0];
  if (w) lines.push(`Worst sale: ${w.title || w.id || "(untitled)"} ${m(r.rankBasis === "profit" ? w.profit : w.payout)}; best: ${b.title || b.id || "(untitled)"} ${m(r.rankBasis === "profit" ? b.profit : b.payout)}`);
  lines.push("Made with the Whatnot Sales Report Analyzer (nothing uploaded). Estimates from the file supplied.");
  return lines.join("\n");
}

// Synthetic, invented sales for the "Load an example" button. Not a real account.
export function sampleCsv() {
  const lines = ["Order ID,Order Date,Product Name,Show,Category,SKU,Sold Price,Shipping Charged,Sales Tax,Commission,Processing Fee,Net Earnings,Cost"];
  let seed = 11;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  const cats = [
    { name: "Trading cards", items: ["Rookie card", "Holo rare", "Graded slab"], price: [12, 90], cost: [6, 40], show: "Friday Card Break" },
    { name: "Sneakers", items: ["Retro high", "Runner", "Slide"], price: [40, 140], cost: [30, 95], show: "Sneaker Sunday" },
    { name: "Vintage", items: ["Tee", "Denim jacket", "Windbreaker"], price: [8, 45], cost: [4, 22], show: "Thrift Haul Live" },
    { name: "Coins", items: ["Silver round", "Morgan dollar", "Proof set"], price: [25, 60], cost: [24, 58], show: "Friday Card Break" },
    { name: "Plush", items: ["Blind box", "Limited plush", "Keychain"], price: [3, 9], cost: [3, 8], show: "Thrift Haul Live" },
  ];
  for (let i = 0; i < 45; i++) {
    const c = cats[i % cats.length];
    const price = Math.round(c.price[0] + rnd() * (c.price[1] - c.price[0]));
    const cost = Math.round((c.cost[0] + rnd() * (c.cost[1] - c.cost[0])) * 100) / 100;
    const ship = 4.5, tax = Math.round(price * 0.06 * 100) / 100;
    const comm = r2(price * DEFAULT_COMMISSION_RATE / 100);
    const proc = r2((price + ship + tax) * DEFAULT_PAYMENT_RATE / 100 + DEFAULT_PAYMENT_FIXED);
    const sold = Date.UTC(2026, 4 + Math.floor(i / 15), 1 + ((i * 5) % 27));
    lines.push([`SAMPLE-${2000 + i}`, dateStr(sold), `${c.items[i % 3]}`, c.show, c.name, `${c.name.slice(0, 3).toUpperCase()}-${String(i + 1).padStart(3, "0")}`, price.toFixed(2), ship.toFixed(2), tax.toFixed(2), comm.toFixed(2), proc.toFixed(2), (price - comm - proc).toFixed(2), cost.toFixed(2)].join(","));
  }
  return lines.join("\n");
}

